-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[32192] = { id = 32192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodlines", description = "We managed to fend off the mogu wardens and their dogs, but many of the blood elves from the scouting party were not as lucky.\n\nMany of my people are trapped inside the ruins to the north. We are devising a solution to break them out, but I believe there may be a more straightforward approach.\n\nGo to the ruins and kill the wardens guarding each prisoner. If my intuition is correct, this will free our comrades.", progress = "These mogu are not to be underestimated.", completion = "We blood elves have served the Horde faithfully. Lately, I wonder what we have to gain from Garrosh's leadership.", objectives = "Free 6 Domination Mages by killing Korune Wardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32193] = { id = 32193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Mogujia", description = "The Explorers' League sent an expedition north some days ago.\n\nWe haven't heard from them since, and I'd sleep better at night knowing our folks aren't in some sort of trouble.\n\nLast I heard, Brann Bronzebeard was heading toward Mogujia in the Kun-Lai Summit.\n\nFind him and report back with their status. Fennie over there can give you a ride if you need one.", completion = "These artifacts must be several thousand years old. Have ye ever seen the like?", objectives = "Find Brann Bronzebeard at Mogujia. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32194] = { id = 32194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Blood", description = "The Explorers' League is here to excavate the ruins, and it's my job to protect them.\n\nWhen we arrived, we found this place crawling with blood elves. Apparently,the Horde are just as interested in the mogu as we are.\n\nThis gives quite an opportunity to thin our enemies' numbers, and steal their findings, too.\n\nSlay any blood elves you find in the ruins, and bring back whatever they are digging up.", progress = "What are those blood elves after?", completion = "Well done, {class}. I knew that you could get the job done.", objectives = "Collect 5 Korune Artifacts from Silvermoon Runeseekers, Dominance Mages, or Dominance Knights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32195] = { id = 32195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anger Remains", description = "From the looks o' our initial survey, this entire area is humming with residual sha energy.\n\nYou know what ta do, {name}. Destroy any last traces ye can find o' the stuff!", objectives = "Kill 27 Angerlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32197] = { id = 32197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Meatloaf", description = "We've been gettin' complaints right and left that the Boss-Lady gets all the good grub and leaves the scraps for the others.\n\nBetween you and I, they may be onto somethin' here. I don't even get to eat as good as she does!\n\nWe need somethin' Sezik can make a lot of that at least attempts to disguise how inedible the food is here...\n\nI got it! Mystery Meatloaf!", progress = "What do ya got for me now?", completion = "I have standards ya know! I'm a chef, not a magician!\n\nThe only mystery here is how Duke thinks he'll pull this over on everyone else!", objectives = "Obtain 7 Chunks of Mystery Meat from the local wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32198] = { id = 32198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Magical, Flying Kingdom's Trash...", description = "Before we enter into a business relationship, I am required by the terms of my rehabilitation program to inform you that I am a recovering potion addict.\n\nThere, now that THAT's out of the way, let's talk portals!\n\nYou see, the big portals in the cities - the ones running all day and night - leak tons of magical energy. It crystallizes around the edges and is generally regarded as trash.\n\nBut I noticed during my, uh... hiatus in the sewers of Dalaran, that these shards still had power.\n\nInterested?", completion = "I knew you would be!\n\nHere's the catch - the shards, in their current state, are unstable. But the soil in this valley is renowned for its magical properties! I am sure if you were to \"plant\" the shard, a very interesting reaction would take place.\n\nIt could stabilize, leaving you with a functioning portal! Or... it might tear open a magical rift that spits out transdimensional horrors!\n\nMy gut tells me it will be a little of both, but there's only one way to know for sure.\n\nHere, take a sample!", objectives = "Speak with Barnaby Fletcher to learn more about Portal Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32199] = { id = 32199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang Steampot", description = "The Boss-Lady desires crabs!\n\nWhy are you looking at me like that? It's not uncommon for a classy person, such as her loveliness, to want crab for dinner. What did you think I meant?\n\nThere are some big crabs wandering around on Bilgewater Beach that should be suitable for her refined palate.\n\nBring Sezik the best crab meat you can find!", progress = "Boss-Lady wants a steampot does she? Well, maybe she should come down here and make it herself!", completion = "This meat is disgusting! It's going to take every spice I have to cover that smell up.\n\nOnly the best for the Boss-Lady!\n\n<Sezik grins and winks at you.>", objectives = "Obtain 5 chunks of Polluted Viseclaw Meat from the Viseclaw crabs on Bilgewater Beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32200] = { id = 32200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangers of Za'Tual", description = "{name}, what I ask of you is little short of genocide, but it is a task that must be done.\n\nFind trolls within their town or on the beach and slay them, for the good of us all.", completion = "Much blood was spilled this day. It is on my hands, {name}, not yours.", objectives = "Slay 12 Trolls in Za'Tual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32201] = { id = 32201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", progress = "The mogu are powerful, but with cunning and tenacity, we can defeat them.", completion = "Excellent. You have dealt the mogu a blow that they shall not easily forget.", objectives = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers, or Shan'ze Thundercallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32202] = { id = 32202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Trolls" }
quests[32203] = { id = 32203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Mogu Spirits" }
quests[32204] = { id = 32204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Horde takes full control of this island, we can look for more permanent solutions.", completion = "One day, this island will belong to the Horde. I can only hope that it will be free of saurok before then.\n\n<Aethas sneers.>\n\nAt least they attack the Alliance, too.", objectives = "Slay 10 Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32205] = { id = 32205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Scout Reports" }
quests[32206] = { id = 32206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Just Won't Do", description = "The Zandalari here are very powerful, {class}. They should not be underestimated. We cannot afford to ignore them as a threat simply because they do not wield swords.\n\nMore arrive every day, and with them centuries of magic knowledge. This threat must be dealt with, and quickly.\n\nAid us in clearing this area, {class}. Perhaps we can even learn something from them in the process.", progress = "Magic can be a great ally or your worst enemy. Let's not leave it to chance.", completion = "It's impressive how easily you were able to cut them down.\n\nPerhaps, it's you they should not underestimate. Thank you for your assistance, {class}.", objectives = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32207] = { id = 32207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in there before they can get their mounted monstrosities out into the open battlefield.", completion = "A trained Zandalari beastcaller with a mount unleashed on the battlefield can kill twenty times their number. Your preemptive attack has saved many lives. Thank you!", objectives = "Defeat 10 Zandalari trolls in the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32208] = { id = 32208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Capacitor", description = "The mines north of here are being used to extract Ghost Iron ore and energize it with lightning energy.\n\nWe need to destroy the drills they use to extract the ore. They are impervious to normal attack, but can be overloaded using the proper methods.\n\nOh - and while you're there, take out whoever is running the operation.", objectives = "Interact with the three lightning drills in the Ghost Iron Mines to destroy them, and kill Metal Lord Mono-Han.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32209] = { id = 32209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Our Scouts!", objectives = "Rescue the three captured Sunreaver agents within the Ghost Iron Mines, and kill Metal Lord Mono-Han.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32210] = { id = 32210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill mogu boss for key, use object behind jumping puzzle" }
quests[32211] = { id = 32211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nalak the Storm Lord" }
quests[32212] = { id = 32212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault on Zeb'tula", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", progress = "We must claim a better strategic position on the island itself.", completion = "Yes! You have done it, champion!\n\nWe will be as a tide that sweeps over this island, bringing with it a new destiny for our people. And you, hero, are at its forefront.", objectives = "Complete the Assault on Zeb'tula. Speak to Lor'themar Theron to begin the attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32214] = { id = 32214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewater Infiltrators", description = "There is nothing more unnerving than walking along, minding your own business, and hearing someone following you. I swear I hear it all over the place down here! We're being watched!\n\nI have a feeling the entire beach is just crawling with spies!\n\nI made some improvements to our infrared goggle tech to put an end to the sabotogery. That's right sabotogery! Now I just need you to try 'em out! Feel free to dispose of any spies you happen to catch.", completion = "Very nice, {name}! I knew it! I knew there were Alliance sneaking around down there!\n\nNo one messes with a Bilgewater rig and gets away with it!", objectives = "Kill 10 SI: 7 Saboteurs around Domination Point and Bilgewater Beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32215] = { id = 32215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heinous Sacrifice", description = "The Zandalari perform heinous rites against our people! They must be stopped!\n\nDelve into the heart of the Za'Tual and destroy their altars.", progress = "This effort should quell their obscene sacrifices for a time.", completion = "I could feel the magic of their altars dissipating even here, {class}.", objectives = "Destroy the Zandalari sacrificial altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32216] = { id = 32216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrible Ptorment", description = "The Zandalari treat their skyscreamer pets as little more than scuttling vermin, bending them to their will with violence and torment.\n\nI can hear one writhing in pain at their hands.\n\nFind the tormented skyscreamer within Za'Tual and help it break free of its captors.", progress = "Have you found the skyscreamer?", completion = "It what?! It killed its master? Wonderful. These skyscreamers  have more fight in them than I realized. Thank you for helping free the beast, {race} - it is one less threat to the Horde, and one more for the Zandalari.", objectives = "Free the Tormented Skyscreamer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32217] = { id = 32217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Offerings", description = "The spirtibinders of the Zandalari perform sacrificial rites to appease the loa and their vile gods. These dark rituals involve the sacrifice of our people.\n\nDestroy any offerings you can find among their tents in Za'Tual and perhaps we can stall the sacrifices.", progress = "I truly hope this helps slow them down. The sacrifices proceed at an alarming rate.", completion = "The tide of blood is slowed, at least for a time. Thank you for your efforts in stalling the sacrifices, {class}.", objectives = "Destroy 6 Zandalari Offerings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32218] = { id = 32218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Enemy", description = "The mogu here at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", progress = "The dead should be allowed to rest.", completion = "Their dead shall rise no more, thanks to you, {name}. Excellent work.", objectives = "Burn 8 Mummified Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32219] = { id = 32219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Cold", description = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable.\n\nUnfortunately, we've received several reports of stone quilen statues coming to life without warning. I can't have these quilen threatening my research expedition.\n\nVenture into the Court of Bones and destroy any quilen statues that you can find.", completion = "I am glad to hear that you left the quilen in a thousand tiny pieces. You have contributed much to our war effort.", objectives = "Destroy 8 Grave Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32220] = { id = 32220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nHorde or Alliance, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", completion = "Thank you, {name}. You have lightened my heart of a heavy burden through your heroic actions.\n\nI will remember your efforts on this day.", objectives = "Save 6 Sunreaver Scouts or Silver Covenant Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32221] = { id = 32221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Beach", description = "Our lumber supply is being jeopardized by constant attacks from Lion's Landing.\n\nWe've been able to keep the attackers at bay, but it's time to really show 'em some muscle!\n\nHead down to the coast and start splitting some skulls!", completion = "Excellent work down there, {name}! That should keep 'em outta our hair for awhile!", objectives = "Kill any 10 Shieldwall Forces including SI: 7 Saboteurs in and around Bilgewater Beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32222] = { id = 32222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Chief Engineer Cogwrench", description = "Wanted for crimes against the Bilgewater Operation!\n\nChief Engineer Cogwrench was last seen building what appeared to be a giant spider tank on the edge of Bilgewater Beach.\n\nExtreme caution should be used when approaching.\n\nA large reward has been posted for Cogwrench's destruction.", completion = "Excellent work, {class}! This brings us one step closer to pushing them out of Pandaria!", objectives = "Destroy Chief Engineer Cogwrench at the edge of Bilgewater Beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32223] = { id = 32223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lieutenant Ethan Jacobson", description = "Wanted for crimes against the Domination Point forces!\n\nLieutenant Ethan Jacobson is responsible for leading several ground assaults against the Bilgewater lumber operation.\n\nLast spotted occupying an island south of Quickchop's Lumber Farm.", progress = "Do not return without his blood on your hands!", completion = "It's a good day when another Lion's Landing leader falls, {class}! Good work!", objectives = "Destroy Lieutenant Ethan Jacobson in the Southern Isles south of Quickchop's Lumber Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32224] = { id = 32224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", completion = "Wonderful work, {class}. This will help our offensive a great deal.", objectives = "Kill 15 Risen Ancestors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32225] = { id = 32225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Dawnseeker Promontory.\n\nThere is no time to delay. You must stop their ritual at once.", completion = "You continue to exceed my expectations, {class}. Well done.", objectives = "Stop the Shan'ze Thundercallers' ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32226] = { id = 32226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Crypts", description = "The Reliquary is having a field day out here, literally!\n\nEvery day, the researchers find more relics to study and catalog.\n\nRecently, one of our adventurers found this scroll at the Court of Bones.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", completion = "Ah yes, you've just confirmed my theory! Thank you, {class}.", objectives = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32227] = { id = 32227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventing a Future Threat", description = "The creatures the Zandalari ride don't start out so big, nor do they start out the vicious and loyal creatures they become.\n\nIf you can frighten some of the hatchling skyscreamers away from the beach, perhaps they will have a chance at a real life.", completion = "You have returned, {race}. It is my hope that these young skyscreamers have the lives they deserve without dealing with the harsh treatment of the trolls.", objectives = "Frighten 12 Hatchling Skyscreamers by running near them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32228] = { id = 32228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", completion = "You are not one to be trifled with. I am sure to have further use of your services.\n\nCome back to me in a day's time, {class}.", objectives = "Kill the Mighty Devilsaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32229] = { id = 32229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Roaming Troll War Party" }
quests[32230] = { id = 32230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", progress = "Have you done as I asked?", completion = "When I give you a task, it gets handled.\n\nWell done, {class}.", objectives = "Destroy the Zandalari Colossus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32231] = { id = 32231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trailing Light in the Dark", description = "There is some dark magic in the Diremoor that extinguishes even our magical illuminations, and so our scouts struggle to find their way.\n\nAs you pass through the swamp, relight any torches you find that our men might find their way. Perhaps they will help you find your way back as well.", objectives = "Relight 8 torches within the Diremoor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32232] = { id = 32232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Inside Counts", description = "I noticed something strange on my last scouting mission. A group of Zandalari are performing a ritual on what appears to be a very large sentry. They may be trying to re-animate it.\n\nWe need that ritual stopped and the sentry destroyed. Anything that large can't be good.\n\nI've sent a scout ahead to observe their actions. Meet with her and figure out how to stop them.", completion = "So I was correct to be concerned. It's a good thing you were there to stop them before that guardian was fully infused.\n\nGood work, {class}.", objectives = "Destroy Guardian Tak'u in Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32233] = { id = 32233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Very Disarming", description = "Look around you, {class}. What do you see? I see an opportunity.\n\nThe casters here work to imbue the Zandalari weapons with powerful magic. As if a sharp blade isn't enough to cut even the strongest foe down to size.\n\nIn my scouting I've noticed the weapons are not very well guarded. This is where you come in...\n\nIf we can steal a few of these weapons we may be able to use them. At the very least they are out of enemy hands.", progress = "So? What did you find?", completion = "Excellent work, {class}!\n\nThese weapons are terrifying on their own, nevermind the magic they are infused with.", objectives = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32234] = { id = 32234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge Is Power", description = "The Zandalari here practice a different kind of magic. We must understand it before we can defeat it, {class}.\n\nTheir control over the arcane and shadow is impressive. I wish to learn how they have achieved what so many others have not.\n\nI believe their ritual artifacts may hold the answers I seek. Bring me a sampling of the artifacts you find, and I will ensure you are rewarded properly.", progress = "Did you find the artifacts?", completion = "These will do nicely, {class}. Excellent work.", objectives = "Retrieve 6 Ritual Artifacts from around Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32235] = { id = 32235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flash! Aaaaaahhhh!", description = "The gnomes have brought their flying contraptions. I want my skies CLEAR!\n\nGet up there on whatever mount you have with you and destroy those paltry devices.\n\nYou may use this grog I \"acquired\" from our goblin allies. It would be better served blasting down gyrocopters than in the gullet of those little green fiends.", progress = "Hellscream's eyes are upon you.", completion = "Ha! Simple mechanical toys are no match for a well aimed bottle of grog.", objectives = "Use the Bilgewater Molotovs to destroy 6 Skyfire Gyrocopter X2s.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32236] = { id = 32236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bug Off!", description = "This cave is crawlin' with nasty shale spiders! How's a girl supposed to get any work done with them gobbling up the miners AND the ore?!\n\nThis seemed like a good opportunity to use my newest invention, Bug Off. See, all you have to do is spray this stuff all over the shale spiders. They hate it and it doesn't seem to have many long term side-effects for the miners!\n\nWhat could possibly go wrong?\n\nTake this handy sprayer and get to work!", progress = "Shale spiders. Why did it have to be shale spiders?!", completion = "Now that's what I like to hear! I bet those spiders will think twice before messing with a Bilgewater operation again!", objectives = "Spray 5 Agitated Shale Spiders with the Bug Off Sprayer and eradicate 12 Shale Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32237] = { id = 32237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Resource", description = "What we have here is too much of a good thing, {name}!\n\nOur rig just can't handle the amount of oil we're pumping out of the ground. It's literally bursting at the seams! To be more accurate, it's bursting at the valves.\n\nI've been working double-time to get the valves repaired, but every time I finish the rounds, they're all broken again.\n\nIt's as if someone is following me... That's ridiculous though....\n\nMaybe you'll have better luck. Try getting as many of those valves tightened as you can.", progress = "Were you able to get those valves tightened?", completion = "So I was being followed! Those dirty rotten sneaks!\n\nI'm going to have to start planting some real nice surprises for those cowards. Surprises that will really knock 'em out!", objectives = "Tighten 8 Faulty Valves in and around Gearslip's Gusher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32238] = { id = 32238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Universal Remote-Explode", description = "The Mecha-Pounders are really making things difficult down here, but I think I may have the solution!\n\nI made this universal remote for myself, but it looks like I hit a specific frequency that has an useful result!\n\nApparently this frequency weakens their armor!\n\nUse the remote to take them down a few notches then punch 'em in the face!", progress = "How'd the remote work for ya?", completion = "Good work, {name}! I saw the fireworks from here!\n\nWho knew being a genius was this easy? I don't even have to try anymore.", objectives = "Destroy 9 Shieldwall Mecha-Pounders in and around Quickchop's Lumber Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32242] = { id = 32242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Secrets", description = "I am told that the mogu once possessed hundreds of hidden armories full of earth-shattering weapons.\n\nWhen a mogu army prepared for war, they struck fear and terror into the hearts of their enemies.\n\nTHIS is the knowledge I seek here on Pandaria!\n\nI have sent an expedition to study some ruins to the west, but they work as slowly as dim-witted peons!\n\nGo speak to Fanlyr Silverthorn, their leader. Tell him that I want to see results immediately.", completion = "The Warchief sent you? What does he say?", objectives = "Speak to Fanlyr Silverthorn at Ancestral Rise in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32243] = { id = 32243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Korune Power", description = "Why hullo there! Have ya ever seen tha like o' these statues? Fascinatin'!\n\nI was scouting up along the ruins earlier, and I spotted somethin' innerestin' up on the highest rise.\n\nI couldn't get close enough, but I think it might be one o' these mogu statues, 'cept it was movin'!\n\nI can't get through all those nasty blood elves, but you look like you could.\n\nWould you mind going up there and bringing me back anything of interest?", progress = "Did ya find anything up there?", completion = "Oh my, look at this thing!", objectives = "Collect a Sha-Touched Claw from the Korune Spellweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32244] = { id = 32244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Korune", description = "These terracotta wardens are fearsome, but not nearly as horrifying as the creature that we found at the top of the ruins.\n\nSome of our surviving scouts reported seeing some kind of mogu spellweaver on the highest rise to the north.\n\nHe practices a type of magic unlike any other we have seen.\n\nWe must learn whatever we can from this creature. Slay him, and bring me anything you find.", progress = "What did you discover?", completion = "Yes, this is remarkable! This is just the kind of artifact that we came here to find!", objectives = "Collect a Korune Codex from the Korune Spellweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32246] = { id = 32246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Scout", description = "It has been two months since the parting of the mists. Alliance scouts, seeking a suitable landing site for the fleet, have engaged Horde forces on a beach in Krasarang Wilds.\n\nMeet with Scout Lynna and help secure the landing site.", completion = "You have impeccable timing, {class}. King Wrynn is just about to land, and the full might of our fleet will follow soon after.", objectives = "Speak with Scout Lynna at Krasarang Cove in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32247] = { id = 32247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A King Among Men", description = "There's no time to waste, we need to find Troteman and secure the beach.\n\nWe should check on the dwarves, too - the Explorers' League is tough, but they're no army. They should be along the cliff just north of here.\n\nLet us ride, {class}. For our friends. For the Alliance.", progress = "The Alliance will be a shield, protecting Pandaria from the Horde.", completion = "I'm satisfied with this site, it's time to bring in our fleet.", objectives = "Accompany King Varian Wrynn to find Marshal Troteman, Hilda Hornswaggle, and slay 25 Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32248] = { id = 32248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Patience", description = "King Varian needs decisive adventurers to help him resolve a showdown between Tyrande Whisperwind and a detachment of Horde warriors holed up in the Temple of the Red Crane.\n\nReport to him immediately!", completion = "Good to see you again, {name}.\n\nWe have a delicate situation on our hands here. We need to plan our next moves carefully.", objectives = "Enter the \"A Little Patience\" scenario and report to King Varian Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32249] = { id = 32249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Scout", description = "It has been two months since the parting of the mists. Horde scouts, seeking a suitable landing site for the fleet, have engaged Alliance forces on a small island off the coast of Krasarang Wilds.\n\nMeet with Scout Rokla and help secure the landing site.", completion = "You are just in time. The Warchief is about to land. Once this site passes his inspection, the fleet will follow.", objectives = "Speak with Scout Rokla at the Horde Landing Site in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32250] = { id = 32250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Warchief", description = "Come, {class}! I want to inspect this island and ensure that my landing team has done their job.\n\nBlood Guard Gro'tash should be somewhere on the northern side of the island looking for a suitable place to build our keep. The goblin survey team will have gone up the eastern coast in search of oil.\n\nLet us crush this pitiful display and claim this land for the Horde!", progress = "Gorehowl thirsts for Alliance blood.", completion = "Well done. Our presence here will not be denied!", objectives = "Accompany Garrosh Hellscream to find Blood Guard Gro'tash, Grizzle Gearslip, and slay 25 Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32251] = { id = 32251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagger in the Dark", description = "Shadow Hunter Vol'jin has joined a group of Kor'kron scouts on an important mission for the warchief.\n\nOf course a proud member of the Horde such as yourself is welcome to go along, but be warned - it could get ugly.", completion = "Good ta see ya, mon. I be needin' true allies at my side for dis mission.", objectives = "Enter the \"Dagger in the Dark\" scenario and report to Vol'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32252] = { id = 32252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of the Loa", description = "Have you heard of the loa? We do not understand all of what it is, but it seems to be a dark magic with some degree of sentience.\n\nWe do not know what power the loa might possess, but I must ask you to put a stop to their rituals, {class}.", completion = "I can only imagine what horrors you witnessed, {name}. Your bravery was put to the test this day, and you did not fail the Horde in your task.", objectives = "Slay 2 Harbingers of the Loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32253] = { id = 32253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REMOVE (No Longer Used)" }
quests[32254] = { id = 32254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", completion = "<The archmage listens carefully to your report.>\n\nI understand. Thank you for your aid, {class}.", objectives = "Check in with Magister Arlan, Magister Sarien, and Magistrix Vesara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32255] = { id = 32255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Sunreaver property under my watch.", completion = "That's more like it.\n\nThank you, {class}.", objectives = "Recover the four stolen Sunreaver Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32256] = { id = 32256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise Of An Empire", description = "Warchief Garrosh Hellscream travels north with a squad of his most elite soldiers.\n\nReport to him with news of our continued victory against the Alliance.\n\nSpeak to Tak-Tak for transportation.", completion = "What do you have to report?", objectives = "Find Warchief Hellscream at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32257] = { id = 32257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voice of the Gods", description = "Too slowly!? We are working as quickly as possible for the Warchief!\n\nWe must excavate carefully, catalogue each find, and of course follow safety procedures. He must understand!\n\nWell, we may have something to show him soon. Do you see that stone statue to the west?\n\nWe suspect it is an ancient stone storage vessel. Now we just have to find a way to open it.\n\nIf you would care to help us with our excavation, please go about it carefully.", progress = "We are quite capable of handling this excavation. I understand the Warchief sent you, but he will get faster results if he leaves us to our work.", completion = "Hmm... very interesting. This tablet will yield many secrets, indeed.", objectives = "Investigate the Mercurial Guardian and obtain the Ancient Korune Tablet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32258] = { id = 32258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Quest Choice: PvP" }
quests[32259] = { id = 32259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Quest Choice: PvE" }
quests[32260] = { id = 32260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Quest Choice: PvE" }
quests[32261] = { id = 32261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Quest Choice: PvP" }
quests[32262] = { id = 32262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captive Audience", description = "The Kirin Tor have gone too far! Now they hold our fellow Sunreavers as war prisoners!\n\nThere will be no discussion of prisoner exchange. We will handle this ourselves.\n\nGo to Violet Rise and free as many prisoners as you can. Do not get captured yourself. We cannot afford to lose you too.", completion = "Those you have rescued today would no doubt thank you, if they had the strength.\n\nOur task here will be ongoing. I refuse to leave anyone behind!", objectives = "Free 5 Sunreaver Captives around Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32263] = { id = 32263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find scout near enemy camp (injured, port him back)" }
quests[32264] = { id = 32264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spellbound", description = "Jaina possesses several very powerful magic artifacts. These items travel with her at all times, and are never far from her grasp. I have an interest in one of these items.\n\nA tome, filled with knowledge, passed from one archmage to another. I have only ever seen glimpses of it.\n\nNow that we fight on opposite sides I see no issue in removing the tome from her possession.", progress = "Do you have it? Do you have the book?!", completion = "I have desired this book for many years, {race}. It's power is too immense to describe. You have done me a great service.", objectives = "Retrieve Jaina's Weathered Spellbook from Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32265] = { id = 32265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charged Moganite", description = "We have been dispatching spies into the Kirin Tor base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Kirin Tor base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", completion = "Well done, champion. This artifact will be put to better use in our hands than in the hands of the Kirin Tor.", objectives = "Recover a Charged Moganite and bring it to High Arcanist Savor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32266] = { id = 32266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Manifestations", description = "Manafiends are nasty creatures. Small and easy to underestimate, but deadly to our magic casters. The Kirin Tor have these pests crawling all over Violet Rise.\n\nWe will need to handle them carefully. Alone they are easily managed, but in groups they become a different challenge altogether.\n\nGo to Violet Rise and cut down their numbers.", completion = "This task will be ongoing, but you have done as a great service, {race}.", objectives = "Kill 9 Kirin Tor Manafiends.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32267] = { id = 32267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy enemy portal near camp (streaming attackers, defended, enemy can use)" }
quests[32268] = { id = 32268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Mana Bombs", completion = "I am sure the use of even these smaller mana bombs has Jaina squirming with rage. Serves her right.\n\nDalaran was my home before her grandparents were born. What right did she have to expel me from my home?", objectives = "Plant a Tactical Mana Bomb on an Alliance Ship, Alliance Supply Shipment, and on the Construct Ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32269] = { id = 32269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Down the Defenses", description = "We need to keep a close watch on the Kirin Tor and their day-to-day activities. Normally this would be easy. We would sneak in a spy and have them report back to us.\n\nHowever, we've run into a slight problem I believe you can help us with.\n\nThe Kirin Tor perimeter wards have increased in power. It's next to impossible to get someone past their lines. If they were disabled we might be able to sneak in before they can be repaired.", completion = "Good work, {class}. With your help we were able to successfully sneak several spies behind enemy lines.", objectives = "Destroy 6 Kirin Tor Perimeter Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32270] = { id = 32270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarm mines near enemy camp (poke them with a stick =P)" }
quests[32271] = { id = 32271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set magical mines around camp (using modern warfare lightning)" }
quests[32272] = { id = 32272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Start and defend summoning ritual near enemy camp" }
quests[32273] = { id = 32273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy summoning circles in enemy camp (BloodElf_PowerOrb_Red)" }
quests[32274] = { id = 32274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", progress = "The saurok value strength above all else. They only respond to strength.\n\nPeace with the saurok will require some amount of bloodshed. The question is, how much?", completion = "I know the true price of bloodshed. I know the cost of war.\n\nIt would be simpler to blindly massacre our attackers until they yield. But is it right?", objectives = "Slay a Skumblade Brute, a Skumblade Saur-Priest, and a Skumblade Seadragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32275] = { id = 32275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surgical Death", description = "The Zandalari train skyscreamers to become ferocious beasts in the skies. The spiritbinders require endless sacrifices - of our people - to be brought to them. And, the jaguar warriors venture ever closer toward the heart of our camp.\n\nFind them in Za'Tual and remove the threat.", completion = "I shall continue my unrest until the threat is subdued, but your aid brings us closer to that goal. I thank you, {name}.", objectives = "Slay 3 Zandalari Spiritbinders, 3 Zandalari Beastcallers, and 3 Zandalari Jaguar Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32276] = { id = 32276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", progress = "Let's tear down this wall.", completion = "With your help, we're one giant step closer to our goal.", objectives = "Speak with Lor'themar Theron, then break into the lower city and secure it for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32277] = { id = 32277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Skies!", description = "We can use the pterrorwing that you found to strike a decisive blow against the mogu. \n\nTheir mining operation is vulnerable to attack from the air, and your pterrorwing is the only beast we have capable of flying out there.\n\nLet me know when you are ready!", progress = "It's time to begin your mission!", completion = "Incredible work. This presents us with a monumental opportunity.", objectives = "Gain access to the Lightning Vein Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32278] = { id = 32278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decisive Action", description = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army.\n\nIf we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure.\n\nI have a plan to do just that, and it won't take an entire army.", completion = "Excellent work! With that blasted warship out of commission, the bombardments on our forces along the coast will cease.\n\nTaran Zhu has informed me that the Shado-Pan will keep vigil over Stormsea Landing, freeing up Sunreaver resources to press the siege elsewhere. Taoshi will be there. I am sure she will be glad to work with you again.\n\nWe are all grateful for your contributions, {name}. Thank you.", objectives = "Infiltrate Stormsea Landing and open the courtyard gate from within. Speak with Taoshi to begin the mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32279] = { id = 32279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Shan Bu", description = "Long ago, Lei Shen found a rare clutch of storm dragon eggs. One of these creatures - Nalak - was particularly brutal, and Lei Shen took it for his own.\n\nThe Thunder King's servant, Shan Bu, works to resurrect Lei Shen's dragon, Nalak.\n\nWe must defeat Shan Bu and, if we are able, prevent him from resurrecting the dragon.", progress = "We must defeat Shan Bu while he is exposed!", completion = "Well done, {name}. Shan Bu's fall will weaken the Mogu and your heroism will surely be remembered.", objectives = "Defeat Shan Bu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32280] = { id = 32280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metalocalypse", description = "You've made a good start, but now it's time to really make a dent in their operations.\n\nTake out Metal Lord Mono-Han,  of the mines.", objectives = "Kill Metal Lord Mono-Han outside the Ghost Iron Mine on the Isle of the Thunder King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32281] = { id = 32281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleshcrafter's End", description = "The mogu responsible for the torture of the agents, Fleshcrafter Goju, stands outside the mine.\n\nKilling him would be the only justice for what he's done to your agents.", objectives = "Kill Fleshcrafter Goju outside the Ghost Iron Mines on the Isle of the Thunder King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32282] = { id = 32282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compy Stomp", description = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", progress = "Say what you will about the Zandalari but none can contest their ability to turn even the most repellant of creatures into a trained weapon.", completion = "We lost three good soldiers when we first arrived on this island. Killed in their sleep by compies that had snuck into their tent. Some nights I still hear the screams.", objectives = "Kill 5 Raptors and 10 Trained Compies in the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32283] = { id = 32283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", completion = "Well done, champion. These beasts are strong enough. We don't need them infused with an angry spirit now do we?", objectives = "Defeat a Loa Speaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32284] = { id = 32284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone You Should See", progress = "It is not my place to choose a side in this war. But I am not going to let a troll who has accomplished so much in his day fall by the wayside.", completion = "Ah! You received my note. Very good. Vol'jin is near death, and I will need your help healing his wounds.", objectives = "Find Chen Stormstout at Binan Village. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32285] = { id = 32285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", completion = "Your efforts are appreciated.", objectives = "Kill 6 Animated Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32286] = { id = 32286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)" }
quests[32287] = { id = 32287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Lor'themar wants them dead. I think you're the one to do it.", completion = "Well done, {class}. Thank you for the help.", objectives = "Kill 7 Shan'ze mogu in the Diremoor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32288] = { id = 32288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering the Defenses", description = "This island holds many dangers for us. Threats loom from every side. We must defend our hold on these shores at all costs.\n\nPerimeter wards have been placed around Dawnseeker Promontory. By default they will inflict damage, but are not fatal in their attack.\n\nNow is not the time to be merciful, {race}. The perimeter wards need to be deadly!\n\nGo and empower the perimeter wards surrounding our camp.", completion = "Now that the wards have been fully armed, we can focus our attention elsewhere. Nothing will be slipping past us now!", objectives = "Empower 6 Sunreaver Perimeter Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32289] = { id = 32289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loot plans, kill boat captain" }
quests[32292] = { id = 32292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", progress = "Well?", completion = "Good work. What you did today brings us one step closer to our ultimate goal.", objectives = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32293] = { id = 32293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Bones", description = "My scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. I need someone capable to see him dispatched. Are you up to the task?", progress = "Is it done?", completion = "It's good to have a man I can trust close at hand.", objectives = "Kill Zur'chaka the Bonecrafter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32294] = { id = 32294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", completion = "You're a good {class} to have around, that's for certain. Thank you.", objectives = "Kill Zur'chaka the Bonecrafter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32295] = { id = 32295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Tome", description = "The tome appears to be written in an ornate, sprawling script that seems to rise off the pages. It vaguely resembles Demonic, but the symbols are far more elaborate than any you've ever seen.\n\nPerhaps one of your demonic companions can tell you more.", objectives = "Speak with your demonic minion to determine the origins of the tome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32296] = { id = 32296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasures of the Thunder King", description = "My scouts have returned with word that more of the treasures from Lei Shen's tomb are being brought up into the citadel. We have access to a secret sewer entrance, but a door bars us from intercepting the shipment. If we're going to succeed in this raid, we will need a key that only the most trusted of Lei Shen's forces carry.\n\nIf you get your hands on such a key, bring it to me.\n\nYou can keep whatever spoils you steal from our raid. I simply want to see that this shipment never makes it to Lei Shen.", progress = "We must disrupt Lei Shen in any way we can. Anything to hinder the rise of his power. Anything to hinder his armies from being bolstered.\n\nIf that means highway robbery, I can live with that.", completion = "Not entirely unsuccessful. Still, we'll do better next time.\n\nThanks for providing us with that key. The raid would not have gone off without you.", objectives = "Speak to Taoshi to enter the Thunder King's Citadel. Inside, provide her with a Key to the Palace of Lei Shen to begin the timed raid on his treasure convoy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32297] = { id = 32297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn or Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", progress = "So... did you decide the devilsaur or the direhorn?", completion = "Few things in this world and beyond are more entertaining than watching a rampaging ancient beast tearing through an enemy's settlement.\n\nIf times were not so dire I would consider selling tickets to such an event.", objectives = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32298] = { id = 32298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", progress = "I heard screaming? Was that your efforts perhaps?", completion = "Very interesting results. I am sure there is a mage somewhere that cares about the specifics. I, on the other hand, am just glad to hear the sound of trolls being assaulted by their own beasts.", objectives = "Find and use Saur Fetishes on 5 raptors, compies, skyscreamers or direhorns in the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32299] = { id = 32299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", completion = "Jobs like this make me glad that I left most of my nose in the tomb.", objectives = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32300] = { id = 32300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming Irony", description = "Well, it would seem the Lady Proudmoore has decided to use our own weaponry against us. Our perimeter wards reported several spies slipping through our defenses carrying tactical mana bombs.\n\nI would enjoy the irony if these bombs were less dangerous.\n\nSearch for these bombs and disarm them. Our wards reported one near the horde ships to the north, one on a bridge to the main isle, and one near our scrying crystals on the eastern side of the Promontory.", completion = "Good work. The real irony is had these been normal bombs we would have had a much harder time detecting them. Some gnomish devilry could have spelled the end of our operation here.", objectives = "Disarm the Tactical Mana Bombs at the Horde Ships, the Scrying Crystals, and the Bridge within Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32302] = { id = 32302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desconstruction", description = "The Kirin Tor constructs are primitive at best. Nevertheless, they pose a threat.\n\nGo to Violet Rise and dismantle Jaina's pitiful war machines. Show the Kirin Tor how easily they can be defeated!\n\nThis will be a message the Kirin Tor cannot easily ignore.", completion = "So the constructs have fallen? Good!\n\nWe will remind Jaina and the Kirin Tor at every turn that the Sunreavers are not to be taken lightly.", objectives = "Destroy 3 Kirin Tor Constructs around Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32303] = { id = 32303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Made for War", description = "Jaina thinks this battle will be easily won. I intend to show her how wrong she is!\n\nThe Kirin Tor brought a weapon with them that must be destroyed. The Arcane Destroyer is a large construct capable of turning the tides of war in their favor.\n\nDestroying this monstrosity would send a very clear message to Proudmoore.", completion = "I wish I could be there to see the look on Proudmoore's face as she mourns the loss of her death machine!\n\nWe can be certain she will build another, but we have at least set her back.", objectives = "Kill the Arcane Destroyer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32304] = { id = 32304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Recognition", objectives = "Your presence on the battlefield cannot be ignored. I would like to give you something extra for your efforts, {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32305] = { id = 32305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overpowered", description = "The Kirin Tor are using mana foci to empower their forces. We cannot allow this to continue.\n\nYou'll find these foci scattered around the outskirts of Violet Rise. Use this mana crystal to destroy as many as you can.\n\nEach mana focus we destroy is another small victory for our cause.", completion = "Excellent work, {class}! It will take them days to rebuild those foci.", objectives = "Destroy 7 Mana Foci around Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32306] = { id = 32306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Collection Tracking" }
quests[32307] = { id = 32307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reader for the Dead Tongue", description = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", completion = "What... where in the great dark did you find this?", objectives = "Bring the codex to a Warlock trainer in your capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32309] = { id = 32309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", progress = "Well, what did you think?", completion = "You are ready to learn more...", objectives = "Read the first chapter of the Legacy of the Masters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32310] = { id = 32310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", progress = "Well, what did you think?", completion = "You are now ready to learn more...", objectives = "Read the first chapter of the Legacy of the Masters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32311] = { id = 32311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlistment Orders", description = "After the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n{name}! The tome you possess may be just the thing we need to convince them to join us in our assault against the Alliance!\n\nFind General Nazgrim in Domination Point and convince him of the importance of your mission.", sourceObjective = "Find General Nazgrim at Domination Point in Krasarang Wilds", sourceObjectiveStatus = "unverified-source-field" }
quests[32312] = { id = 32312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlistment Orders", description = "After the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n{name}! The tome you possess may be just the thing we need to convince them to join us in our assault against the Horde!\n\nFind Admiral Taylor in Lion's Landing and convince him of the importance of your mission.", sourceObjective = "Find Admiral Taylor in Lion's Landing in Krasarang Wilds", sourceObjectiveStatus = "unverified-source-field" }
quests[32313] = { id = 32313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt Helheim", description = "{name}... You've heard correctly. Warchief Garrosh tasked me with tracking down this Council of the Black Harvest.\n\nUnfortunately, I have heard word that the Alliance is ahead of us. I heard that some Human Warlock by the name of Hareem Helheim has information which will help us locate them.\n\nHead to Lion's Landing, infiltrate their base and obtain the documents before Helheim's courier departs. Show Helheim no mercy.", objectives = "Obtain the second part of Legacy of the Masters from Hareem Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32314] = { id = 32314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaughter Selenora", description = "{name}... You've heard correctly. King Varian tasked me with tracking down this Council of the Black Harvest.\n\nUnfortunately, the Horde is seeking them out as well. One of my spies recently sent word that Shadowmancer Selenora has the second piece of their journal.\n\nHead to Domination Point, slaughter Selenora and bring back whatever you find on her rotting cadaver.", objectives = "Obtain the second chapter of Legacy of the Masters from Shadowmancer Selenora in Domination Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32315] = { id = 32315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduin's Plea", description = "Ah, just the {class} I was looking for. I have received an urgent letter from the young Prince Anduin.\n\nHe is playing host to his father, King Wrynn, and several other Alliance dignitaries at the Shrine of Seven Stars in the Vale of Eternal Blossoms.\n\nAccording to his most recent correspondence, something bad is happening at the city.\n\nPlease go at once and speak with him. I must settle some affairs here at Lion's Landing, but I will join you soon.\n\nSpeak to Fennie if you'd like a ride to the Vale.", completion = "Well met, {class}. We have much work to do here.", objectives = "Find Anduin at the Shrine of Seven Stars. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32316] = { id = 32316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart Of The Alliance", description = "I can't believe this has happened, {name}. After all we have been through here on Pandaria, will our people never learn from their past mistakes?\n\nBrann's expedition returned recently from Mogujia, bearing a sample of sha for study.\n\nI had my reservations about this endeavor in the first place, and my worst fears have been realized.\n\nThe sha has escaped containment. I do not need to explain the horror of bringing the sha into the heart of the Vale.\n\nWe must dispel any sha we can find, and quickly!", progress = "We must protect this land, and our people, from the sha's influence.", completion = "I see that you and my son have been hard at work. Thank you for taking the initiative to aid our cause here in the Vale.", objectives = "Confront 6 Sha-Touched Footmen. Should you lose Prince Anduin, speak to him at The Imperial Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32317] = { id = 32317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Soulstones", description = "{name}, take this - the journal of Jubeka Shadowbreaker.\n\nRead the journal and use the information contained within to track down where she went.\n\nFind her soulstones and use them to locate her.", objectives = "Read Jubeka's Journal and use the clues within to locate the four soulstone fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32318] = { id = 32318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regeneration Takes Time", description = "Vol'jin would be dead if he were any race other than a troll. His regeneration is impressive, but it is being blocked by a poison.\n\nWe need to cleanse this poison so that he can regenerate the damage.\n\nTake to the skies and travel southeast. Across the mountain tops of the Secret Aerie you will find needle sprites. Bring me some of the hardest needles from them you can find.\n\nWith them I can attempt an acupuncture technique that should purge the poison from his body and accelerate his regeneration.", progress = "My herbs are the only thing keeping Vol'jin from death. I dare not leave his side.", completion = "Very good. These should work nicely.", objectives = "Collect 10 Sturdy Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32319] = { id = 32319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Thrall!", description = "<Vol'jin half opens an eye and begins to move his lips as if to speak.  Though no sound comes, you decipher two words.>\n\nFind Thrall.\n\n<With an effort, Vol'jin thrusts a hearthstone into your hands and then passes out.>", progress = "You have come a long way to see me, {race}. Speak.", completion = "<Thrall stares at the stone you have handed him.>\n\nVol'jin's hearthstone? My friend, has it come to this?", objectives = "Find Thrall by using Vol'jin's Hearthstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32320] = { id = 32320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Is Family", completion = "Vol'jin has saved my life many times in the past. To see my own Kor'kron used against his people cuts deeper than I can put into words.", objectives = "Escort Thrall to the Echo Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32321] = { id = 32321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Monkey King", description = "Ever since the Horde captured the Divine Bell I have been searching for a means to counter its power.\n\nMy research got as far as this tomb. I am going inside. If you follow me, I will share the rest as we go.\n\nIf we get separated, meet me back here at the entrance to the tomb. Speak to me when you are ready to proceed.", completion = "You come asking for the Monkey King?\n\nLet us see how well you ookin' sing.\n\nWho are you, so tiny and boring?\n\nYour cause is silly! You leave me snoring.\n\nThree riddles I will ask,\n\nThese riddles are a task,\n\nFinish each without pause,\n\nAnd we shall see if I help your cause.", objectives = "Help Anduin Wrynn find the Monkey King in the Valley of Emperors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32324] = { id = 32324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Signal", description = "The soulstone shards fuse together easily in your hands.\n\nStrangely, no soul is stored within the stone. Instead, the stone seems to be drawing power from somewhere in Shadowmoon Valley. Looking east, you feel the power linked beyond the mountains, to the very gates of the Black Temple.", objectives = "Follow the soulstone to the gates of the Black Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32325] = { id = 32325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Black Temple", description = "It's clear that Jubeka's soulstone has lead you here to the Black Temple. \n\nThe question remains... why?\n\nThe only remaining option is to head inside and figure out why they were here.", completion = "You have done more for this world than you can know, {class}. It is... something of a shame Kanrethad met this end. A shame, but inevitable.", objectives = "Look for Jubeka's mark on the main entrance of the Black Temple. Once inside, speak to Jubeka at the Temple Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32326] = { id = 32326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insertion", description = "{name}! You'll do perfectly.\n\nWe know where the Alliance have hidden the Divine Bell. We've already inserted an agent into enemy territory, we just need you to help him execute his mission.\n\nPack up, {name}. You're headed to Darnassus.", completion = "{name}! So glad Nazgrim selected you.\n\nIt's taken a great deal of the Horde's effort to get you here through Jaina's traps. Maintaining our illusion this close to Darnassus is considerably expensive.\n\nFurthermore, the Sunreavers of Dalaran are risking their neutrality by assisting the Horde with this operation.\n\nIn other words, we expect only the best from you.", objectives = "Use the Sunreaver Portal in Domination Point to secure a teleport to Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32327] = { id = 32327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darnassus Mission", description = "The Divine Bell is in the city. We don't want to cause a scene, we just want the artifact. I need you to find a way in, WITHOUT getting caught. That means no mounts, no flying, no fighting.\n\nI can provide aid. I will magically cloak you, so you may move with stealth. I will also give you a small charm that you may use to return to safety, should you get in trouble.\n\nNow go, {name}. Go, locate the bell, and tag it to be teleported back with you.", progress = "The bell, {name}!", completion = "Well executed, {race}! I knew we could count on you.\n\nNow to get off this wretched tree.", objectives = "Locate the Divine Bell.\n\nYou may use the Silvermoon Charm to return to Fanlyr if you get in trouble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32328] = { id = 32328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victorious Return", description = "The portal by my side will return you safely to Domination Point. I will return behind you; I must clean up our tracks a bit before we leave, so that Proudmoore doesn't discover our involvement.", completion = "You found the bell! And Fanlyr teleported it to Silvermoon for study, as instructed? The Horde will put this to good use.\n\nYou have done the Horde a great service today. Lok'tar, friend!", objectives = "Report your success to Nazgrim at Domination Point in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32329] = { id = 32329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get My Results!", completion = "The Warchief \"demands\" progress? His impatience is growing more destructive with each command.\n\nAs it stands, we could use your expertise.", objectives = "Speak with Lor'themar Theron in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32330] = { id = 32330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in the Box?", description = "We are trying to uncover the secrets of one of the mogu artifacts Garrosh insisted we investigate. It is proving most difficult, as anyone who probes it magically is greatly affected by raw, negative emotions.\n\nI called in the assistance of Arch-mage Aethas of the Sunreavers in the hopes that he and Rommath could crack this puzzle. They asked for you specifically - apparently you have some relevant experience?\n\nGo to the chamber below Farstrider Square east of here and see if you can assist them.", completion = "This reckless use of my people by Garrosh is becoming intolerable. If you had not been here to assist I dread to think what might have happened.", objectives = "Assist with Aethas and Rommath's experiment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32331] = { id = 32331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kirin Tor", completion = "I am glad to see you friend. While I have learned much about diplomacy I think Jaina is too familiar with my tactics.\n\nI could use a friendly hand in resolving this conflict.", objectives = "Use the Portal to the Purple Parlor in Lion's Landing and meet with Anduin Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32332] = { id = 32332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Riddle: Mercy", description = "So, you wake up the Monkey King for a mallet hmmm? Answer first, these riddles three, and then the mallet you shall see.\n\nFirst riddle!\n\n  \"Softly singing a song of pain\n\n    There is a creature tortured and lame.\n\n    Way down south and beyond the wall,\n\n    It hides from its wikket masters' call.\n\n    Seek out the creature sad and somber,\n\n    And free it from its untamed amber.\"\n\nBring me the untamed amber.", progress = "Ah, the wise-ish thing returns. Have you my amber?", completion = "Ah! Amber! Fresh and untamed. Did you kill to get it? But of course.\n\nThough free, the untamed amber is a dangerous thing, and many might die because of it.\n\nMercy comes in many forms, like spikes and mantid and really ookin' spooky storms.", objectives = "Find the object the Monkey King described in his riddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32333] = { id = 32333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Riddle: Fellowship", description = "You want to stop the Divine Bell? We need the mallet first.\n\nYou want the mallet? We need to be friends first.\n\nYou want to be friends? We need a Metal brew first. \n\nYou want a Metal brew? You need to go to the Shrine of Fellowship first. \n\nYou want to go to the Shrine of Fellowship? Great! It's in the Jade Forest southeast of the Tian Monastery.\n\nRing the bell and get the Monkey King some brew while there. Oh... you may have to fight for it.", progress = "You have the Metal Brew?", completion = "The Metal Brew is strong and lasting, a brew to be shared with friends after a battle.\n\nEmperor Shaohao and his Monkey King had many a round in our day. Many battles, and many good friends.", objectives = "Obtain Metal Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32334] = { id = 32334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Riddle: Strength", description = "The mallet you seek is not a toy for children,\n\nIt calls trouble like the song of a siren.\n\nA test of strength the Monkey King will require,\n\nBefore you receive this tool of your desire.\n\nAt the Temple of the White Tiger you will find\n\nA challenger to test how well you are resigned\n\nStep through the main door and then turn right down the ramp\n\nChallenge the ook waiting for you there like a champ!", completion = "Why engage in duelery? Why engage in foolery?\n\nYou ask the Monkey King for an artifact of power, I have to make sure when the time comes you will not cower. One tough dooker you think you might ookin be, but against mogu, many will turn and flee.", objectives = "Defeat the Challenger at the Tiger Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32335] = { id = 32335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greatest Prank", description = "So riddles three you answered me. Good good. The Monkey King is not so old that he tells just anyone his tricks.\n\nIt was the greatest prank ever!\n\nYou want to hear story of the Mallet and the Monkey? Too bad! No choice!", progress = "What you think?", completion = "It looks like it is going to take us a few days to track all of these \"minions\" down.\n\nThank you for your help, {name}. Meet me in Lion's Landing in a few days and we will embark to track down these objects.", objectives = "Listen to the Monkey King's story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32336] = { id = 32336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Handle", progress = "Ingoo was a great hozen. Good leader, nice parties, and good booze.", completion = "Artifacts not make people great. Artifacts allow people to be more of themselves. Good becomes gooder. Bad becomes badder. And Chief Ingoo Ingoo became worser.", objectives = "Recover the Mallet Handle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32337] = { id = 32337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Head", description = "Monkey King receive word on where to find the head,\n\nThe hozen who got it has long since been dead. \n\nKunzen chiefs pass the relic from father to son, \n\nBut then virmen Skiggit came and the head it won. \n\nNow the wikket worships it in a hollow. \n\nSince it was too ookin' big for him to swallow. \n\nI sent a royal finder north to find him and stand. \n\nLook for finder in mountains west of the Heartland.", progress = "You got head?", completion = "What virmen do not understand, they worship, fight or flee.\n\nI should send them a few statues of me.", objectives = "Recover the Mallet Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32338] = { id = 32338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harmonic Ointment", description = "Legends are not born, they are made.\n\nMuch like your next target, a mogu named \"The Blade.\" \n\nIn his bags you will find,\n\nAn ointment whose sound plays with the mind.\n\nBring this nibby ointment to the Monkey King!\n\nAnd with it, he shall make the mallet sing!\n\nTravel north along the wall, and when you reach the end, turn left.", progress = "How the mogu found the ointment is a wonder.\n\nBut a lot has happened since the world tore assunder.", completion = "Woot woot!", objectives = "Recover the Harmonic Ointment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32339] = { id = 32339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuilding the Mallet (Tracker)", description = "Time for the fixing and then time for the mixing!", objectives = "Obtain the Harmonic Mallet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32340] = { id = 32340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder the Black Temple", description = "While Akama and his men are dealing with the demons, there is nobody to stop you from stealing a relic or two...", completion = "You've looted everything you could grab on your way up. Time to tally up your plunder and hide it before Akama catches up...", objectives = "Loot everything you can grab and reach the end of the Den of Mortal Delights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32341] = { id = 32341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonstrate Your Power", description = "Akama and his men are under siege by the forces you unleashed in the Reliquary of Souls. \n\nDemonstrate your power to Akama by saving his men from the demonic forces!", objectives = "Slay the demons who are attacking Akama's men in the Halls of Anguish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32342] = { id = 32342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit Trap", description = "Within the ruins we have identified several powerful mogu artifacts. They trapped spirits within, probably to use them in some ritual or conjuration.\n\nThey are a type of device that we haven't identified and desperately need to study - they may reveal more of the secrets of the mogu's spirit binding techniques. \n\nGo, find us a few samples so that we may continue a proper study.", progress = "Have you brought the traps?", completion = "Ahh, yes. Hmm. Hand that over. Carefully.", objectives = "Collect 3 Spirit Traps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32343] = { id = 32343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogudei's Lieutenants", description = "There are two extremely powerful mogu spirits that the Alliance unearthed in their ineptitude.\n\nThese are choice targets for us, {class}. If you kill them and collect each of their essences, we could make great progress on decoding the history of this strange ruin.", progress = "The essence isn't going to make itself, {race}.", completion = "What treasures! With any luck, the spirits will return and we will be able to sample their essence further.", objectives = "Collect Meng-do's Essence and Gen-li's Essence in the Ruins of Ogudei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32344] = { id = 32344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Is A Mystery", description = "We have detected several... anomalies in these mines, of an arcane or spiritual nature. They are disrupting our attempts to discern the nature of the magic used in the spirit binding rituals here.\n\nThey are quite elusive, but we've managed to isolate the arcane signature of one of these anomalies, and one of our mages has enchanted this bauble with its signature.\n\nTake the bauble. It will begin to glow more brightly as you approach the anomaly. Once you reach it, you can use the bauble to draw it out.", progress = "We are still dealing with that anomaly! Hurry!", completion = "Ahh, yes. I received word from one of our researchers that they are no longer troubled by that anomaly. Well done.", objectives = "Use the Arcane Bauble to find an anomaly within the Ruins of Ogudei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32345] = { id = 32345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Not Monsters!", description = "The Reliquary may have had a bad name in the past, but we're not monsters. We simply hold different views about archaeology than the Explorers' League.\n\nWe do focus on performing acts of heroism from time to time. So go, liberate some of the pandaren slave spirits in the ruins.", completion = "Ah, good work. As much as it may seem trivial in comparison to our larger research goals, it is important that we maintain appearances, {name}.", objectives = "Liberate 14 Troubled Slave Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32346] = { id = 32346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oi Ain't Afraid o' No Ghosts!", description = "Look. We got a nasty problem here, and ol' Troteman back at Lion's Landing's gonna throw us out of here if we don't get things under control.\n\nGive us a hand, please!", completion = "Alright! We'll be back up and runnin' in no time!", objectives = "Kill 12 Spiritbound Mogu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32347] = { id = 32347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviction Notice", description = "The bloody Reliquary's snuck into the ruins. They've taken the lower section and are conducting all kinds of magical shenanigans down there.\n\nIt's time we gave 'em an eviction notice, in the form of your boot in their rear!", progress = "Did ye' deliver the message?", completion = "Ha! That should send 'em runnin' back to Silvermoon with their tail 'tween their legs!", objectives = "Kill any 10 members of the Reliquary in the Ruins of Ogudei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32348] = { id = 32348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick 'em While They're Down", description = "The Alliance may think they have a stranglehold on the ruins, given that their base of operations is close.\n\nWe're going to disabuse them of that notion. Go take out some of their guards.", completion = "Oh, what a fine day. Alliance fools defeated, and our research is moving ahead quite nicely.", objectives = "Kill 12 Lion's Landing military units.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32351] = { id = 32351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Thunder", description = "Ah, {name}, we meet again. I have heard some wondrous news.\n\nHigh Chieftain Baine Bloodhoof of the tauren has arrived here on Pandaria.\n\nHe meets with Warchief Garrosh Hellscream and Regent Lord Lor'themar Theron now, at the Shrine of Two Moons in the Vale of Eternal Blossoms.\n\nHe sent me a strange request - to send him a loyal champion of the Horde, capable of combat... and discretion.\n\nI can think of none better to send than you. Speak to Tak-Tak if you seek transport.", completion = "Well met, {class}. You were sent from Domination Point? Very well. We have much to discuss.", objectives = "Find High Chieftain Baine Bloodhoof at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32352] = { id = 32352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering Storm", description = "If General Nazgrim sent you, then I trust you are capable of discretion.\n\nWhen I arrived here, I found Garrosh... experimenting... with some ancient power that he found in the mountains to the north.\n\nHe believes that this \"sha\" can strengthen our soldiers.\n\nUnfortunately, so far the results have been quite the opposite.\n\nOur troops are erupting into random violence. Go and interrogate them. If they threaten you, be prepared to defend yourself.", progress = "There is great power here... Why is it that so many fear it?", completion = "You bested my defenders? Finally, one who can control his hatred and violence!\n\nI need more men like you.", objectives = "Confront 6 Sha-Touched Grunts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32355] = { id = 32355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harmonic Mallet", completion = "I am glad you made it, my friend. I could really use your help with what is to come. My father would prefer I remain in the safe custody of his legion.\n\nBut if there is one thing Pandaria has taught me, it is a few people in the right place at the right time can make a bigger difference than the greatest of armies.", objectives = "Find Anduin at the Tomb of Conquerors. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32356] = { id = 32356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Ambassadors Summoned", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.", objectives = "See the scouts off, then speak to Big Lu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32357] = { id = 32357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Event Complete", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.", objectives = "See the scouts off, then speak to Big Lu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32358] = { id = 32358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soulcore" }
quests[32359] = { id = 32359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of the Naaru", description = "The soulcore has transformed into a crystal. This is clearly the artifact that Kanrethad and Jubeka were attempting to create, but you still have no idea where they went.\n\nSeek out the Black Prince in the Tavern of the Mists and see if you can acquire some information on where they went.", objectives = "Bring the Eye of the Storm to Wrathion in the Tavern in the Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32360] = { id = 32360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaiting the Black Harvest", description = "{name}, I have never heard of this Council of the Black Harvest. However, the fact that they are interested in my father's power concerns me greatly.\n\nHowever, I do have... contacts, who may be able to help us track them down. Most of my agents are preoccupied with the Alliance and Horde battle in Krasarang. Once that has settled down, I will help you.\n\nFor now, feel free to leave the Naaru relic in my protection, or not - just don't end up dead somewhere at the bottom of a swamp.", sourceObjective = "Wait for Wrathion to contact you.\n\n[To Be Continued in Patch 5.2...]", sourceObjectiveStatus = "unverified-source-field" }
quests[32361] = { id = 32361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Event Complete", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.", objectives = "See the scouts off, then speak to Big Lu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32362] = { id = 32362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Dalaran", description = "Jaina is refusing to hear me out. Father was hoping I would have some pull with her, but I think she still sees me as a child.\n\nYou, on the other hand, are a hero of the Alliance and I know she respects your deeds.\n\nIs there something you can say to her to convince her we need her help?", progress = "We are not asking for military forces. But we do need the magical support of Dalaran if we are to stop Garrosh's reckless advances.", completion = "Thank you for your help, hero. I hear the wisdom in Jaina's words.\n\nLet's hope her faith in the Sunreavers is justified.", objectives = "Speak with Jaina Proudmoore and hear her story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32363] = { id = 32363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kun-Lai Expedition", description = "I have another message for you from High Chieftain Bloodhoof.\n\nIt seems you've made quite the impression on him.\n\nHe travels with the Warchief's vanguard into Kun-Lai Summit, to the north. They have set up an outpost, Garrosh'ar Advance, just east of One Keg.\n\nYou had best not keep him waiting. Speak to Tak-Tak for swift travel.", progress = "Thank you for coming so quickly.", completion = "Thank you for coming, {name}.", objectives = "Find Baine Bloodhoof at Garrosh'ar Advance. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32364] = { id = 32364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Medicine", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to find the ingredients for me.\n\nThe recipe can be found in a book near my other things, just behind me.", sourceObjective = "Find the recipe for Memory Wine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32365] = { id = 32365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Epilogue Complete" }
quests[32366] = { id = 32366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lick of Fire", description = "6 Ruqin Firewine. This intense liquor helps relax the mind, allowing the recovery of past memories.\n\n<Scrawled along the side is another note.>\n\n(Note: May result in a terrible hangover.)", objectives = "Collect 6 Ruqin Firewine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32367] = { id = 32367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of Yak", description = "3 Fresh Yak's Milk. Helps strengthen teeth and bones. Allows imbibers to return from their dream state.\n\n<The now-familiar handwriting now leaves a cryptic message.>\n\n(Why do all yaks look alike!?)", objectives = "Collect 3 Fresh Yak's Milk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32368] = { id = 32368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory Wine", description = "The tincture is ready. Now, drink.", progress = "What did you see?", completion = "What did you see, {class}?", objectives = "Drink the Memory Wine and witness Shan Kien's Past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32369] = { id = 32369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Past" }
quests[32370] = { id = 32370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kun-Lai Expedition", description = "Glory to the Alliance, {class}. We are making gains against the Horde in the Krasarang Wilds, albeit slowly.\n\nWhile we hold the front here, we need your help to fight a different battle - one that strikes at our enemy's heart.\n\nOur SI:7 informant, Agent Connelly, has sent word that a Horde vanguard is moving up into the northern reaches of Kun-Lai Summit.\n\nGo without delay. Make contact with Agent Connelly in the field, and find out what is going on.\n\nSpeak to Fennie over there for a flight in.", completion = "<You do a doubletake when the Pandaren suddenly speaks with Connelly's voice.>\n\n'Bout time, laddie! I've been waitin' fer ya to show up.\n\nThese Pandaren are good people but can't mix a martini fer nothin'.", objectives = "Find Connelly at the Grummle Bazaar. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32371] = { id = 32371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory Wine", description = "<The radio static crackles, and Agent Connelly continues speaking.>\n\nNow comes the real challenge, <laddie/lassie>. \n\nHead on over to the center of camp and see what you can overhear.", completion = "Back so fast, rookie? So what did ye learn?", objectives = "Use the Kor'kron Disguise to enter the camp. Then drink the Memory Brew and witness Shan Kien's past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32372] = { id = 32372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Subjugation", description = "The Kor'kron have been trained to be the finest, most loyal soldiers of the Warchief. Their presence here means that Garrosh fears an uprising.\n\nVol'jin and his people are as much a part of the Horde as any orc.\n\nWe must break this occupation and free the trolls. It pains me to say this, but you must eliminate enough of the Kor'kron so that the trolls can retake their city. Then meet me at Darkspear Hold so we might challenge their officer directly.", progress = "How did it come to this? It is as if the word \"honor\" is lost on these orcs.", completion = "The orcs have changed. My Horde has changed. Do I kill my fellow orcs until it is once again \"my\" Horde? Do I have any right to try force the Horde to be what it once was?\n\nThese are troubling times. But for now, I must see to Vol'jin's people.", objectives = "Defeat 10 Kor'kron Overseers, 5 Kor'kron Subjugators, and Gul'tar the Subjugator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32373] = { id = 32373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. The Alliance has landed on the shores with the full might of its navy. Your King aims to check Horde aggression in this new land.\n\nGarrosh Hellscream is propelling the Horde headfirst into battle, but King Varian Wrynn is a little more of a mystery to me. Do you have a moment? I'd like to talk to you about this leader of yours.", completion = "I am curious to see how King Wrynn rises to the occasion.\n\nI am even more curious to see what YOU are capable of. Let's find out...", objectives = "Speak with Wrathion at the Tavern in the Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32374] = { id = 32374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Alliance deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", completion = "Marvelous! Even in the midst of the chaos of battle you've proven that an individual can have an impact. The Horde has learned that their actions in Pandaria will not be unopposed.\n\nI believe it is time for a more substantial challenge...", objectives = "Kill Horde forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32375] = { id = 32375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dash of That", description = "100 Buttonbelly Mushrooms. Must be freshly harvested from a wet, dark place.\n\n<Scrawled along the edge of the page is a hand-written note.>\n\nFungus is very good for the health! (Or it might kill you, cause serious illness, rash, hallucination, or loosen bowels. Note to self - MUST be careful when selecting wild mushrooms!)", objectives = "Collect 100 Buttonbelly Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32376] = { id = 32376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Valley!", description = "This sealed communication was sent for you, along with urgent orders to travel to the Valley of Emperors in Kun-Lai Summit.\n\nThis looks serious. I'd not delay if I were you.\n\nSpeak to Tak-Tak for transportation.", completion = "Ah, good. You have come. \n\nAgain, I apologize for the cryptic note - but Garrosh is increasingly distrustful of us. I do not want this operation disturbed by hasty action on his part.", objectives = "Find your \"Friend from Silvermoon\" at the Valley of Emperors. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32377] = { id = 32377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Kor'kron In Our Midst", description = "Garrosh is hell-bent on finding that Divine Bell. I wouldn't be surprised if he tore Kun-Lai Summit apart to find that artifact.\n\nThe Warchief's called a gathering at Garrosh'ar Advance, just to our north.\n\nI need to stay here to monitor troop movements, so you'll have to infiltrate their camp and overhear their discussion.\n\nGo to Garrosh'ar Advance and steal some Kor'kron Armor from Reavers, Honor Guards, and Scouts.\n\nTake this radio earpiece. Don't contact me... I'll contact you.", progress = "Just as you look at the assembled Kor'kron disguise, your radio earpiece crackles.", completion = "<Agent Connelly's voice comes over the radio.>\n\nEy, you're good! I knew those Kor'kron wouldn't be a problem fer ya. Couldn't've done much better meself.", objectives = "Collect 1 Kor'kron Helmet, 1 Kor'kron Armor, and 1 Kor'kron Boots, then combine them into a Kor'kron Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32378] = { id = 32378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing a Path", description = "First thing's first. If we're going to take the leader captive, we'll need to thin the numbers of his agents.\n\nBe careful. These mogu are particularly dangerous - they appear to be manipulating the sha in ways we haven't seen before.", completion = "Good. We should be ready to make our move.", objectives = "Kill 10 Korune Mogu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32379] = { id = 32379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Korune", description = "I'm not prepared to throw away more of our people fighting against an enemy we don't know or understand. \n\nSee if you can find any clues in the area as to who exactly these \"Korune\" mogu are. A contingency in case this operation doesn't go as planned.", progress = "Have you found anything on the mogu?", completion = "Good. There's quite a bit to pore through here... \n\nI will have the Reliquary investigate these. Surely we can use them to discern more of the secrets of these Korune mogu.", objectives = "Find the document Legacy of the Korune in the Valley of the Emperors, and collect the Sealed Korune Artifact and Korune Orders from Korune Mogu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32380] = { id = 32380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Around", description = "We're going to need help if we hope to figure out Garrosh's plans for Pandaria.\n\nI have someone specific in mind, but he will not be easy to convince.\n\nAgent Connelly considers himself retired, but one does not simply leave the SI: 7. We've had an undercover agent following his every move for months.\n\nCurrently, he is disguising himself as a high roller at Bizmo's Brawlpub. Something about settling an old debt.\n\nMeet with our undercover agent in the Brawler's Guild.", progress = "So you think you are going to talk Connelly out of retirement? Good luck!", completion = "Following Connelly has been interesting to say the least. The man is a master of disguise!\n\nTalking him into joining you won't be the hard part, {class}. Figuring out which of these lively individuals is him will be next to impossble.", objectives = "Report to undercover agent Townsley in Bizmo's Brawlpub in the Stormwind side of Deeprun Tram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32381] = { id = 32381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch A Spy", description = "Now, I could tell you who Connelly is, but that would be too easy! To catch a spy you have to think like a spy.\n\nYou have to pass the test first!\n\nThe small things can say a lot about a person. It's all in the details.\n\nI'm going to give you a drink to deliver. I will give you a small detail about something the recipient is wearing. From there it will be up to you.\n\nBe careful who you pick to give drinks to. People here tend to get pretty hostile if you give them the wrong order!", progress = "You learn to look at the details when you barkeep.", completion = "You have a keen eye, {class}! I think you are ready to meet Connelly.", objectives = "Deliver the Pink Marmot, the Mogu Melon Twist, and the Rusty Dagger to the correct patron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32382] = { id = 32382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's In Deep", description = "Agent Connelly has managed to infiltrate Garrosh's camp in Kun-Lai! He's been following their every move.\n\nConnelly requested you specifically to assist him in gathering some vital intelligence.\n\nHe sent along a disguise for you. Make sure you put it on before approaching the camp! It will no doubt be heavily guarded.\n\nHe insists you will know him when you see him. Something about your keen eye for details...\n\nGo talk to Fennie over there for a drop-off.", completion = "You've arrived just in time. From the intel I've gathered, Garrosh is hot on the trail of some sort of ancient mogu artifact of power.\n\nIf we can figure out what he's after, we can stop him from getting it!\n\nWe have to act fast to gather as much information as possible.", objectives = "Meet Connelly in Kun-Lai Summit. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32383] = { id = 32383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bugging Out", description = "I've managed to plant a few bugs around the camp, but there could always be more.\n\nI disguised the bugs to look like statues. They blend in perfectly with the other artifacts lying around.\n\nYour disguise should allow you to move freely around the camp. Just don't go near the dog and don't linger around Garrosh! Nero and Garrosh will see through your disguise.\n\nIf you get caught I can't help you. I can't compromise the mission!", progress = "How'd it go?", completion = "Well done! Everyone always underestimates the little guys and it is always a grave mistake!", objectives = "Plant the Cleverly Disguised Bugs in the large tent, near the small tents, and in the supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32384] = { id = 32384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapping the Leader", description = "It is time to make our move. Go to the Tomb of Shadows, weaken him, and take him captive.\n\nI will stay here in case Garrosh arrives. He must be delayed so that we can take our prize before he destroys it in his anger.\n\nHurry!", progress = "Move, {name}!", completion = "We managed to capture our quarry. \n\nIn truth, though, I am not sure what our next move should be. I will contact the leaders of our allies and see if they have ideas - I don't know that our arcane talents are going to pry the secrets of our mogu captive.", objectives = "Weaken and capture Shan Kien at the Tomb of Shadows in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32388] = { id = 32388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Command", description = "There's an orc general I've been keeping a close eye on. Warlord Bloodhilt curried a lot of favor with Garrosh Hellscream by beating back an Alliance advance in Southern Barrens. He's now entrenched within the fortress at Domination Point.\n\nI doubt the Alliance can take him out. But... you've proven me wrong before.\n\nIf you wish to finish him off, bring friends. Lots of friends.", completion = "<Wrathion grins.>\n\nYou were being tested, {class}. I knew you were capable of great things by yourself.\n\nBut you have proven to me that you have the makings of a leader, cobbling together support among a group of strangers in the midst of a battlefield.\n\nThe Alliance is fortunate to have you.", objectives = "Kill Warlord Bloodhilt at Domination Point in Krasarang Wilds. You will need a group.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32389] = { id = 32389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lion Roars", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", completion = "<Wrathion hungrily listens to tales of your exploits on the battlefield, his eyes gleaming bright red.>\n\nOhh... oh! Incredible! In the very eye of battle, one's true heart is revealed.\n\nYou do not disappoint, {name}.\n\nNeither does your Alliance.", objectives = "Win battles at the Temple of Kotmogu and the Silvershard Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32390] = { id = 32390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Packmaster", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on your King. Would you be interested to hear what I've learned?", completion = "<A strange device sits within an ornate silk-lined chest. It appears as though it can be fastened to your sha-touched weapon as an additional upgrade. The empty socket is disconcerting; you feel as though it is staring back at you. A single, hollow, judgmental eye...>", objectives = "Speak with Wrathion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32391] = { id = 32391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Korune", description = "Garrosh sent a hundred riders to search the northern coast of Kun-Lai Summit, to seek a mogu crypt matching the one you saw in Shan Kien's memory.\n\nOut of those, one found the resting place of the Divine Bell.\n\nBlademaster Ishi is leading an advance party to secure the bell now.\n\nGo and assist him. Defend that artifact from anyone who might stand in your way!\n\nSpeak to Tak-Tak without delay. He can take you there.", completion = "The Alliance beat us here. How could this happen?", objectives = "Find Ishi at the Ruins of Korune. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32392] = { id = 32392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divine Bell", description = "If the Alliance thought they could steal the Divine Bell from us, they were wrong!\n\nEven now, we have them trapped in the crypts beneath us.\n\nDeath will be the price they pay for defying us.\n\nCome, {class}. Let us show them the error of their ways.", completion = "Darnassus, is it?\n\nThe Alliance believes they have won the day. Now, when their arrogance is at its greatest, is our opportunity to pluck the prize from their fingers.", objectives = "Kill Sarannha Skyglaive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32393] = { id = 32393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Korune", description = "It's time for our boldest move yet, {name}.\n\nSince you acquired intel on the location of the Divine Bell, we've amassed a top team to excavate the artifact without delay.\n\nCommander Sarannha Skyglaive leads the expedition into the northern-most reaches of Kun-Lai Summit.\n\nJoin them at once, and use whatever skills you need to make the endeavor a success.\n\nGood luck, {class}. I don't need to tell you how important this mission is to the Alliance.\n\nSpeak to Fennie. She'll get you there quickly.", progress = "Looks like we're well ahead of the Horde. Not surprising, but we must act swiftly.", completion = "We blasted the doors open moments ago, {class}. You arrived just in time to join us for the excavation.", objectives = "Find Sarannha Skyglaive at the Ruins of Korune. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32394] = { id = 32394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divine Bell", description = "There's no telling what lies below, so I will lead the initial scouting party myself.\n\nIf your report was correct, then the Korune mogu hid the Divine Bell in the rooms below our very feet.\n\nI have a feeling they would not have left such a precious artifact unguarded.\n\nI could use a capable {class} such as yourself to watch my back. Let me know when you're ready.", completion = "Fantastic work, {name}. I could not even imagine the atrocity that Garrosh would commit if this bell were to fall into his hands.\n\nToday, we have secured a safe future for the Alliance. I will see to it that the bell makes it safely to Darnassus.\n\nI will extoll your deeds to the King.", objectives = "Kill Dreadweaver Avartu and recover the Divine Bell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32395] = { id = 32395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Saw Avartu" }
quests[32396] = { id = 32396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncompletable Binding Quest [DND]" }
quests[32397] = { id = 32397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Won't Even Miss It", description = "I've noticed Garrosh and that Reliquary blood elf carrying around some sort of journal.\n\nThe journal is never more than a stone's throw away. It must be important!\n\nIf you can cause enough of a distraction, you may be able to swipe the journal off the table.\n\nThese yaks might just do the trick. Give one of 'em a tap and they'll do the rest.\n\nJust be ready to move fast!", progress = "What did you find?", completion = "Phew! That was a close one! I never doubted you for a minute though.\n\nNow let me take a look at that journal...", objectives = "Create a distraction in the camp and steal the Weathered Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32398] = { id = 32398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bell Speaks", description = "Your efforts have culminated in this moment, {class}.\n\nWarchief Garrosh gathers the most elite champions of the Horde in Kun-Lai Summit to witness the ringing of the Divine Bell.\n\nYou have more than earned the right to participate.\n\nGo now. The dawn of the new Horde begins today.\n\nSpeak to Tak-Tak. He should be able to secure your travel arrangements.", completion = "I was wondering when you would arrive, {name}.", objectives = "Find Malkorok at Emperor's Reach. Speak to Tak-Tak at Domination Point for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32399] = { id = 32399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Darkest Shadow", description = "It is time, {name}. We have traveled a long path to reach this moment.\n\nToday, our Warchief, Garrosh Hellscream, will change the course of our people's history forever.\n\nToday, we witness the birth of Garrosh's Horde!\n\nDo not let anything interfere with the ceremony!", progress = "We cannot rely on fate or destiny. We must carve out our own future... the future that WE deserve!", completion = "They may have destroyed the Divine Bell, but I have taken the life of the Alliance's prodigal son!\n\nIt is nothing less than my own father would have expected of me.\n\nThis victory may have come at a high cost, but it is of little consequence.\n\nI will find other ways to destroy my enemies, and bring glory to the Horde!", objectives = "Witness the ringing of the Divine Bell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32400] = { id = 32400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bell Speaks", description = "Horde forces are amassing in huge numbers at the Emperor's Reach, high up in the mountains of Kun-Lai Summit.\n\nThe area is an ancient mogu palace, and certainly a source of untold power.\n\nThis can only mean one thing. Garrosh is going to use the Divine Bell, and Anduin... and the Harmonic Mallet... are both missing.\n\nI have no doubt that the fool boy went north by himself.\n\nI don't have time to gather an elite force to detain him. You must go and stop Anduin.\n\nFennie can take you.", completion = "{name}! Just the {class} I was hoping to see. You couldn't have arrived at a better time.", objectives = "Find Anduin at Emperor's Reach. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32401] = { id = 32401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Darkest Shadow", description = "Garrosh is right over there, and he's going to ring that bell at any moment.\n\nWe don't have time to wait for my father's army. This is our only chance to stop him!\n\nI'll attempt to appeal to his senses before resorting to using the Harmonic Mallet.\n\nCharge in whenever you're ready, {name}. I'll be right behind you.", completion = "<Anduin looks like a crumpled doll. He lays as still as a stone, and the only movement comes from the frigid air ruffling his fair, golden hair.>\n\n<You sit quietly for a while, until the cold settles into your bones. The bell is destroyed, but the silence is deafening.>\n\n<Out of the corner of your eye, you see the slightest flicker from the boy's hand. You lean in close. He breathes - but just barely! Anduin is alive!>", objectives = "Defeat Ishi and destroy the Divine Bell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32402] = { id = 32402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Situation In Dalaran", description = "The night elves learned that the Divine Bell was stolen. This much we anticipated.\n\nHowever, they've also found out that the \"neutral\" Sunreavers of Dalaran were complicit. Now, we've got a situation.\n\nI need you to go to Dalaran. Speak with Kromthar for a ride. You are to rendezvous with Grand Magister Rommath once you arrive.", completion = "Good... you've arrived. It's not a good day to be Horde in Dalaran.\n\nJaina's called for the exile of all the Sunreavers. You and I are going to save as many as we can - including Archmage Aethas Sunreaver himself - and then get out of here as fast as possible.", objectives = "Speak with Kromthar to obtain a ride to Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32403] = { id = 32403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Starts in the Sewers", description = "Compared to the rest of the city, this part of the sewers is relatively calm. This is good - we can extract more Sunreavers in peace than we can in war.\n\nFind as many citizens as you can. Tell them that it is not safe here, that they must leave the city at once.\n\nAnd try to stay clear of the Silver Covenant. We don't want to cause a scene if we can avoid it. Not yet, anyhow.", progress = "I think I see a few more Sunreavers over there...", completion = "Let's press on.", objectives = "Evacuate 9 Sunreaver Citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32404] = { id = 32404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violence in the Arena", description = "As I suspected, it gets worse up ahead. The Silver Covenant is outright attacking innocent Sunreavers!\n\nThis cannot stand. While our prime directive is to rescue Aethas Sunreaver, we must also protect as many blood elves as we can.\n\nI will continue to scout ahead. Fight well, {class}!", completion = "So much bloodshed! In a place of peace!\n\nJaina has gone too far this time.", objectives = "Slay 6 Silver Covenant Enforcers and 4 Silver Covenant Spellbows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32405] = { id = 32405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand of the Silver Covenant", description = "Every Sunreaver Jaina expels from this city is a new blade that fights for the Horde. For US.\n\nI'm off to gather more strong elves. You've proven your hand in combat thus far - go take care of that creep in the black market.\n\nWhen you're done, we'll meet at the ramp and prepare to go aboveground.", completion = "The first stage of our mission is complete. That was the easy part.\n\n<Rommath takes a deep, measured breath, then continues...>", objectives = "Slay Sorin Magehand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32406] = { id = 32406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tactical Assault", description = "If we're to survive up above ground, we're going to need a base of operations.\n\nI'm going to try to take the center of the city. It's risky, but hopefully Jaina and the Silver Covenant won't expect it.\n\nStay by my side now, {name}.", completion = "Now, let's move quickly.", objectives = "Follow Grand Magister Rommath into the center of Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32408] = { id = 32408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silver Covenant's Stronghold", description = "I have it on good authority that Archmage Aethas Sunreaver is being held in the Silver Enclave, home of the Silver Covenant. Arcanist Rathaella holds him in captivity.\n\nMost Covenant agents are out slaughtering Sunreavers right now, which means our chance is ripe. Slay Rathaella, and spring Aethas from his prison.", completion = "We will continue saving Sunreavers for a while longer. Aethas' location may become clearer as we press on.", objectives = "Slay Arcanist Rathaella.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32409] = { id = 32409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kirin Tor's True Colors", description = "Any pretense that the Kirin Tor might have had at being a \"neutral\" group can officially be discarded. I'm now hearing that Jaina's got Alliance troops stowed away near Antonidas Memorial.\n\nThe area's free of Sunreavers, but it still makes my blood boil to see such blatant favoritism from the Kirin Tor.\n\nGo visit the memorial, {name}... and give those Alliance dogs a good kick on your way through.", progress = "<Rommath looks displeased.>", completion = "Thank you for that, {name}.\n\nIt unsettles me to have to fight directly with the high elves of the Silver Covenant... but I never tire of slaying Alliance.", objectives = "Slay Lieutenant Corwin and 10 of his troops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32410] = { id = 32410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus' Landing", description = "We can rescue as many Sunreavers as we want, but if they can't escape, then there's no point.\n\nThe Silver Covenant will certainly be subduing and killing the Sunreavers' dragonhawks. Put a stop to it.", progress = "The depravity of this Silver Covenant sickens me. Attacking innocent creatures!", completion = "Well done, {name}. Well done.", objectives = "Free 6 Sunreaver Dragonhawks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32411] = { id = 32411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Remaining Sunreavers", description = "There's still a number of significant Sunreavers who haven't been accounted for. Odds are that they're in the Sunreaver's Sanctuary, caught by surprise.\n\n<Rommath hands you an artifact, clearly made by blood elf hands.>\n\nThe place is crawling with Silver Covenant. You'll need to get in, use the Tear to evacuate the VIPs, and then get out.\n\nStay alive, {name}.", progress = "Be on the lookout for Aethas while you're in there.", completion = "Excellent. They should be waiting for us in Silvermoon when we return.", objectives = "Use the Tear of the Sin'dorei on Uda the Beast, High Arcanist Savor, Magister Hathorel, Magister Surdiel, and Magistrix Vesara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32412] = { id = 32412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Grasp", description = "We've looked everywhere he's likely to be, except for one place: the Violet Citadel.\n\nFind out if Archmage Aethas is being held within the citadel, {name}. We may get lucky. If not... at least we saved a number of lives today.", completion = "Is this... {name}? What's going on here?", objectives = "Slay Mage-Commander Zuros, then escape from Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32413] = { id = 32413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Return to Krasarang", description = "Wherever your loyalties might lie - with Rommath and I, with Garrosh, or elsewhere - one thing is true: your acts today were truly heroic.\n\nI can arrange for your transport back to Krasarang Wilds. Speak with me if you would like passage back to Pandaria, {name}.", completion = "<Nazgrim listens as you recount the day's events.>\n\nWe take the bell... and the Alliance takes Dalaran. That escalated quickly.\n\nWar is coming, {name}. Be on your toes.", objectives = "Report to General Nazgrim at Domination Point in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32414] = { id = 32414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus Attacked?", description = "As you know, our night elven allies moved the Divine Bell you retrieved to Darnassus for safekeeping and study. Moments ago, they portaled some Highbourne mages over here to ask for backup. Details are hazy - some sort of stealth attack on the city?\n\nI don't know what to make of it, but Jaina Proudmoore is already on the scene and I suspect they need all the help they can get.\n\nSpeak to Seamus Goldenkicks over there for a quick portal to Darnassus. Find Jaina!", completion = "The Bell is gone...\n\nAt the scene of the crime, we found traces of arcane magic... I may be able to use my skills to track the thieves.", objectives = "Speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus, then speak with Jaina once you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32415] = { id = 32415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Tracks" }
quests[32416] = { id = 32416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina's Resolution", description = "For too long, I have toiled to mend fences between Alliance and Horde. Time and time again, I've given the Horde the benefit of the doubt - and time and time again, they stab me in the back.\n\nI refuse to be betrayed again! If the Horde intends to use the Kirin Tor as a weapon against the Alliance, then they have no place in Dalaran.\n\nCome with me, {name}.", progress = "<Jaina looks angry.>", completion = "I will instruct you from here on out.\n\nJaina will be going down into the city to enforce our new rules.", objectives = "Use the portal from Darnassus to Dalaran, then speak with Vereesa Windrunner on the other side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32417] = { id = 32417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sewer Cleaning", description = "Jaina's doing a good job taking care of Sunreavers above ground, but there's still plenty rooting around in the sewers.\n\nGo find those lying rats and exterminate them!", progress = "<Vereesa looks out over her city.>", completion = "It's nice to have those rats out of here for good. Well done, hero.", objectives = "Slay 12 Sunreavers in the Dalaran Sewers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32418] = { id = 32418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfair Trade", description = "Most shopkeepers in the Magus Commerce Exchange have sided with the Silver Covenant, but there remain a few holdouts that must be taken care of.\n\n<Vereesa shows you a list of names.>\n\nThey will not go easily.", completion = "While I can't say I agree completely with Jaina's methods, I do understand her motives.\n\nSometimes, you have to fight back.", objectives = "Slay Inkmaster Aelon, Tolyria, Gearmage Astalon, and Sintharia Cinderweave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32419] = { id = 32419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Hide", description = "The Sunreaver's Sanctuary is still crawling with those Horde-loving Sunreavers.\n\nJaina will have sent the reasonable ones to the Violet Hold. The rest refuse to leave, raising their weapons against us.\n\nShow them the cost of their defiance. They now face the judgment of the Alliance, the Silver Covenant, and the Kirin Tor!", completion = "This is a bloody day, {name}, and this is bloody work.\n\nBut do not forget what the Sunreavers did to bring this on: They used neutral Kirin Tor resources to aid the Horde in their fight against the Alliance.\n\nDo not hesitate to believe that they would do the same to us, given the chance.", objectives = "Slay 16 Sunreavers in the Sunreaver's Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32420] = { id = 32420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cashing Out", description = "I just saw one of the Sunreavers - Brasael, I think his name was - running off in the direction of the bank to the north. No doubt he's trying to gather whatever assets he can before he leaves.\n\nHead him off and make sure he doesn't steal any resources from our coffers. He relinquished whatever funds he left in the bank when he and his Sunreaver kind betrayed us.", completion = "I suppose it wasn't enough for him to be a coward and a backstabber... he had to be a greedy thief as well.\n\nHmph. The Horde and the Sunreavers aren't all that different. They deserve one another.", objectives = "Slay Magister Brasael.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32421] = { id = 32421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Run", description = "Compliant Sunreavers will be sent to the Violet Hold. Defiant ones are put to the sword.\n\nNONE are to escape.\n\nThe Sunreavers keep their dragonhawk mounts on Krasus' Landing. Take this dust, and use it to render them incapable of flying.\n\nOr kill them. I don't care.", progress = "We can't have the Sunreavers escaping and plotting counterattacks against Dalaran. We need to be quick, precise, and thorough.", completion = "Now, the Sunreavers have to answer to us. Jail or death - their fate is in their own hands.", objectives = "Render 5 Sunreaver Dragonhawks incapable of flying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32423] = { id = 32423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Had To Be Done", description = "Thank you for your aid today, {name}. I will be handling the purge from here on out.\n\nJaina will soon be off to Lion's Landing, to speak with King Varian. She asked for your attendance.", completion = "I can't fault you for following orders. In fact, I can't really fault Jaina for acting on her own behalf, for once.\n\nBut still... we aren't playing a game here. We are dealing with war, with people's lives, with the future of the Alliance itself.\n\nAt the very least, we now have the Kirin Tor on our side. Today will be remembered by all as a victory for the Alliance.", objectives = "Speak with Vereesa Windrunner to travel to Lion's Landing, then speak with King Varian Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32426] = { id = 32426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirred, Not Shaken", description = "Alright, I'll tell you how to find Connelly.\n\nAgent Connelly is currently posing as the high roller, Professor Kilt. He spends most of his time in the Boom Room. Rumor has it he's after one of the fighters for some long forgotten betrayal.\n\nUnfortunately, the lounge is by invitation only. Lucky for you I just happen to have an invitation.\n\nTry not to look too obvious when you walk past the bouncers. If you get caught you didn't get this pass from me.\n\nIn fact you and I have never met!", completion = "So the SI: 7 needs a reminder in what the word retirement means?\n\nI suppose they wouldn't be comin' to me if the situation weren't dire.\n\nI'll help, but I'll need a few days to gather some intel.", objectives = "Find Professor Kilt in the Boom Room in Bizmo's Brawlpub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32427] = { id = 32427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. Your Warchief aims to impress the Pandaren with the full might of the Horde's military. He will lay claim to the resources of this land, with or without Pandaren aid.\n\nI understand your leader's aims, but I really want to understand the Warchief himself. What drives him? And where is the Horde ultimately going? I'd like to talk to you about this leader of yours.", completion = "Like all great leaders, Garrosh has greatly extended himself. Just what is he ultimately capable of?\n\nMore importantly, what YOU are capable of? Fresh bloodshed along the coast gives us an opportunity to find out...", objectives = "Speak with Wrathion at the Tavern in the Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32428] = { id = 32428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Spirit Tamer", description = "Legend tells of legendary pandaren spirits that roam the lands of Pandaria.  Find them and defeat them in a pet battle.", completion = "I can't belive you took out those spirits!", objectives = "Defeat all of the Pandaren Spirits in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32429] = { id = 32429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Horde deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", completion = "Marvelous! Even in the midst of the chaos of battle you've proven that an individual can have an impact. The Alliance buckles under Horde might, although their King refuses to break.\n\nI believe it is time for a more substantial challenge...", objectives = "Kill Alliance forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32430] = { id = 32430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Command", description = "There's an Alliance dwarf I've been keeping a close eye on. High Marshal Twinbraid proved to be a nuisance in Southern Barrens when he struck back at the Horde after the loss of Bael Modan. He's now entrenched within the Alliance stronghold in Lion's Landing, helping to orchestrate the Krasarang counter-offensive.\n\nOnly a legendary group of Horde heroes could possibly defeat him.\n\nIf you wish to finish him off, bring friends. Lots of friends.", completion = "<Wrathion grins.>\n\nYou were being tested, {class}. I knew you were capable of great things by yourself.\n\nBut you have proven to me that you have the makings of a leader, cobbling together support among a group of strangers in the midst of a battlefield.\n\nThe Horde is fortunate to have you.", objectives = "Kill High Marshal Twinbraid at Lion's Landing in Krasarang Wilds. You will need a group.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32431] = { id = 32431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glory to the Horde", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", completion = "<Wrathion hungrily listens to tales of your exploits on the battlefield, his eyes gleaming bright red.>\n\nOhh... oh! Incredible! In the very eye of battle, one's true heart is revealed.\n\nYou do not disappoint, {name}.\n\nNeither does this Horde of yours.", objectives = "Win battles at the Temple of Kotmogu and the Silvershard Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32432] = { id = 32432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul of the Horde", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on Garrosh Hellscream. Would you be interested to hear what I've learned?", completion = "<A strange device sits within an ornate silk-lined chest. It appears as though it can be fastened to your sha-touched weapon as an additional upgrade. The empty socket is disconcerting; you feel as though it is staring back at you. A single, hollow, judgmental eye...>", objectives = "Speak with Wrathion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32433] = { id = 32433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undermining the Under Miner", description = "Grezik Oregrind has become a nuisance that must be eliminated.\n\nThis land responds to all of our actions as I am sure you are aware, {class}. Because of this, we cannot allow the goblins to haphazardly destroy it.\n\nOur scouts have reported Sha emerging from Oregrind's Dig. The brains behind the operation is a goblin named Grezik Oregrind.\n\nDestroy him and perhaps we will stall the operation just long enough to contain the Sha.", objectives = "Destroy Grezik Oregrind at Oregrind's Dig.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32434] = { id = 32434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Pandaren Spirit", description = "You're back!  Up for another battle with me?", progress = "Think you can take me?", completion = "I will get you next time!", objectives = "Defeat Burning Pandaren Spirit in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32435] = { id = 32435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Place", progress = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to get second place!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
quests[32436] = { id = 32436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Place", progress = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to be awarded the third and final prize!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
quests[32437] = { id = 32437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Saw Sarannha 1" }
quests[32438] = { id = 32438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Saw Sarannha 2" }
quests[32439] = { id = 32439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flowing Pandaren Spirit", description = "You're back!  Up for another battle with me?", progress = "Think you can take me?", completion = "I will get you next time!", objectives = "Defeat Flowing Pandaren Spirit in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
