quests[32441] = { id = 32441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thundering Pandaren Spirit", description = "You're back!  Up for another battle with me?", progress = "Think you can take me?", completion = "I will get you next time!", objectives = "Defeat Thundering Pandaren Spirit in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32442] = { id = 32442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Danger", description = "Our scouts have sighted a fel command ship looming on the horizon, Grandmaster. It appears to be headed on a collision course with the Wandering Isle.\n\nWe should prepare our troops for the worst case situation - an all out attack.\n\nIn the meantime, let us send our champions ahead to try and divert the Legion ship's attention.", progress = "The command ship appears to be gunning straight for us. We need everyone on alert, now!", completion = "Our champions defeated the first wave of attackers, but the command ship is nearly upon us!", objectives = "Complete the mission, \"Impending Danger.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32444] = { id = 32444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Earned Brawler Title (Weekly)" }
quests[32446] = { id = 32446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dis-Assembly Required", description = "Those shredders are becoming a problem down there, {class}.\n\nWe've sent in the Mecha-Pounders, but it just isn't enough. They're getting damaged faster than we can repair 'em!\n\nI happened upon this strange remote while scouting. With a little bit of re-configurin' I think we can use it.\n\nTry usin' it on the Jungle Shredders. Hopefully it will destroy them and then you can bring me the scrap metal.", progress = "So what did that remote do?", completion = "Goblin construction leaves somethin' to be desired, but it'll have to do. Good work, {name}!", objectives = "Destroy the Jungle Shredders using the Re-Configured Remote and then collect 6 pieces of Scrap Metal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32448] = { id = 32448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ties with the Past", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to recover the essential ingredient for me. We need the spirit essence of a mogu that lived in the time of the memory we wish to see.\n\nYou should be able to find just such a spirit inside the Path of Conquerors, to the northeast.", progress = "You never know what you will find in a book. Especially an ancient pandaren one.\n\nI'm eager to see how this Memory Wine works.", completion = "Ah, very good. This is the last thing we needed.", objectives = "Recover the Spirit Essence of Varatus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32449] = { id = 32449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Ogudei", description = "Our scouts at Sparkrocket Outpost have reported some new activity near an area called the Ruins of Ogudei.\n\nWe need to gather intelligence on what it is the Alliance are doing, and more importantly what it is they found. We cannot afford to have any unknowns.\n\nMeet up with Belloc Brightblade in Sparkrocket Outpost and find out what he knows.", completion = "We have a lot of work to do, {class}. Who knows what has already been uncovered in Ogudei!", objectives = "Report to Belloc Brightblade in Sparkrocket Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32450] = { id = 32450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Time Is Now!", description = "Now we take the fight to them, {class}!\n\nReport to Shademaster Kiryn in Sparkrocket Outpost. She will have your orders.\n\nNow we'll see how they handle the full might of the Horde rushing at their precious keep!", completion = "Now things can get interesting! I have a few plans for Lion's Landing...", objectives = "Report to Shademaster Kiryn in Sparkrocket Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32451] = { id = 32451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send A Message", description = "It's time we show these Horde mongrels the full strength of the Alliance! Today we bring the battle to their door.\n\nReport to Admiral Rogers aboard the Skyfire. She will have further instructions.\n\nGood luck out there, {class}. Do the Alliance proud!", completion = "The battle is already underway, {class}. Let's get you out there!", objectives = "Report to Sky Admiral Rogers aboard the Skyfire in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32452] = { id = 32452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then There Were Goblins", description = "We're fighting a war on all fronts, {class}. Even Pandaria itself needs our protection.\n\nThe Bilgewater goblins are destroying land that doesn't belong to them. They must be stopped!\n\nReport to Sky Admiral Rogers aboard the Skyfire. From her vantage point she should have a good idea of where their weak spots are.", completion = "It's about time we dealt with this nuisance. Those Bilgewater runts need to be taught a lesson!", objectives = "Report to Sky Admiral Rogers aboard the Skyfire in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32455] = { id = 32455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silence", description = "D..did we... do it?\n\n<Anduin mumbles the words, even though the effort clearly costs him.>\n\nL..look... in.. my... bag...\n\nUse... flare...", completion = "I hesitate to guess what would have happened if you had not been there with the young Prince, {name}.\n\nToday, you put an end to Garrosh's plans.\n\nYou have undoubtedly saved thousands of lives, and most importantly, you brought Anduin back to us.\n\nWe are doing everything we can for the boy, but we can only wait and see.\n\nI believe he has the fight in him. I must believe it...", objectives = "Use the Alliance Flare Gun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32457] = { id = 32457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunder King", description = "Are you aware of recent events in Kun-Lai Summit? The Zandalari have landed on the northern shores in great numbers and have set about renewing old alliances. To that end, they have resurrected The Thunder King.\n\nEven among the mogu, the name of the first emperor commands awe and fear. The Thunder King founded a vast empire of slavery and suffering... but also of power, riches, and splendor.\n\nWe will take the fight to him soon. Find me when your faction makes its move.", completion = "The Sunreavers and the Kirin-Tor are mounting an assault on the Thunder King's base of operations! My new friend here and I were just discussing the ramifications of their attack.\n\nYou and I can stand to benefit from the situation, {name}. I have a few ideas...", objectives = "Contact Wrathion on the second floor of the Tavern in the Mists in the Veiled Stair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32458] = { id = 32458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n{name}! My father's fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our ships to these shores. We just need to collect charms of good fortune to make it happen.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", objectives = "Collect Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32459] = { id = 32459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n{name}! The Horde fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our brothers and sisters to these shores. We simply need to collect charms of good fortune to gain fortune's favor.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", objectives = "Collect Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32460] = { id = 32460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Thieves", description = "We WILL get to the bottom of this.\n\n{name}, you're coming with me. We'll search every inch of this city if we have to, but we'll find out how they took the bell... and where.\n\nI'm picking up traces of arcane magic here... we need to follow the trail!", completion = "I've decided.\n\nCertain members of the Kirin Tor have put their allegiance to the Horde above the order, and I will NOT tolerate it. This is nothing short of a betrayal.\n\n<Jaina's eyes flare with rage.>\n\nCome with me, {name}. We're going to clean up Dalaran.", objectives = "Help Jaina discover who took the Divine Bell, and where they took it. You may speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32461] = { id = 32461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Order of the Cloud Serpent", description = "Ahhh, it seems you have found yourself the proud owner of a majestic cloud serpent.\n\nBefore you may fly the skies on this powerful creature, you must first earn the skill to ride it.\n\nThe Order of the Cloud Serpent can teach you the knowledge that you seek.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", completion = "Ah, have you come to join the Order?", objectives = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32468] = { id = 32468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Clarity", description = "You know, there is a way we can improve your S.E.L.F.I.E. cam, if you're interested. With the right focusing lens, I could add all kinds of features to that thing.\n\nI've heard that way out on old Yojamba Isle in Stranglethorn Vale, the mother of all basilisks has been seen. Her hide is dotted with gems that'd make the perfect lens, if I could get my hands on them.\n\nShe's not going to go down easy, though. You might want to bring some friends along.", progress = "That crystal spine matriarch has the gems we need to upgrade your lens, any luck with that?", completion = "Count me surprised to hear from you again, you must be tougher than I thought. You've earned my respect, kid, here's your lens upgrade kit. Now get out there and take some S.E.L.F.I.E.S!", objectives = "Collect 1 Pristine Crystal Shard from the Crystal Spine Matriarch on Yojamba Isle in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32469] = { id = 32469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Clarity", description = "Hi again! Oh, I forgot to tell you! I've devised a foolproof way to improve your S.E.L.F.I.E. cam! \n\nIn fact, with just the right gemstones, I can make a lens that would allow us to do all sorts of things!\n\nSome fellow explorers have told me about a large basilisk out on Yojamba Isle in Stranglethorn Vale. Her hide is dotted with tons of high-quality crystals! What a perfect coincidence!\n\nShe sounds pretty tough, though! You should bring some friends!", progress = "Hey, stay out of my shot! Oh, it's you! Did you take down that basilisk yet?", completion = "I knew from the moment we met that you were an adventurer, just like me! Here's your lens upgrade kit, now get out there and take some S.E.L.F.I.E.S!", objectives = "Collect 1 Pristine Crystal Shard from the Crystal Spine Matriarch on Yojamba Isle in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32470] = { id = 32470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Camera Action", description = "Oh, hi! Isn't this a great shot? I love my S.E.L.F.I.E. camera!\n\nDo you want me to make you one, too? I only need a few parts!\n\nFor the strap, I'll need a Russet Belt from one of the armor merchants in Stormwind.\n\nI've already ordered more housings, you're welcome to take one, you just have to find where my shipment ended up!\n\nOh, and a Standard Scope, most any engineer can make you one of those.\n\nOk, are you ready for a little photography action?!", progress = "Look at this shot? I could shoot here all day! Did you get those parts yet?", completion = "Great! I've just gotta put this box here, and jam this part in here... and done!\n\nHere's your new S.E.L.F.I.E. cam, enjoy!", objectives = "Collect an Iron Box and a Russet Belt from locations within the capital, and a Standard Scope from an engineer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32471] = { id = 32471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Camera Action", description = "You look like you've got a discerning eye for the visual arts, want to try your hand at photography?\n\nI can make you one of these S.E.L.F.I.E. cameras, I just need a few parts.\n\nFor the strap, grab me a Russet Belt from one of the armor merchants around here.\n\nI've got a shipment of extra housings waiting by the back entrance to the city, grab me one when you're over there.\n\nOh, and a Standard Scope, most any engineer can make you one of those.\n\nNow get out there, kid. Fame awaits!", progress = "You got those parts for me, or what? I'm busy here!", completion = "You're all set, kid. You've got a face the camera will love, now get out there and get shooting!", objectives = "Collect an Iron Box and a Russet Belt from locations within the capital, and a Standard Scope from an engineer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32474] = { id = 32474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Valor", description = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.>\n\nThere! My eye is upon you, {class}. I am watching.\n\nThe Pandaren, like the Alliance, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course.\n\nProve your bravery to me, {name}!", completion = "<Wrathion nods slowly.>\n\nYes, {name}. I saw your deeds, and I was most impressed.\n\nYou are truly an instrument of change.", objectives = "Gain the \"A Test of Valor\" Achievement by earning a total of 3000 Valor Points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32475] = { id = 32475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spark of Life", description = "The Thunder-Laced Egg burns your hand as you hold it. You recall that Yalia Sagewhisper of the Shado-Pan discussing the history of the Thundering Cloud Serpents, perhaps she will know what to do with it.", objectives = "Deliver the Thunder-Laced Egg to Yalia Sagewhisper on the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32476] = { id = 32476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Valor", description = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.>\n\nThere! My eye is upon you, {class}. I am watching.\n\nThe Pandaren, like the Horde, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course.\n\nProve your bravery to me, {name}!", completion = "<Wrathion nods slowly.>\n\nYes, {name}. I saw your deeds, and I was most impressed.\n\nYou are truly an instrument of change.", objectives = "Gain the \"A Test of Valor\" Achievement by earning a total of 3000 Valor Points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32477] = { id = 32477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Player is Back in Time" }
quests[32485] = { id = 32485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering the Defenses", description = "This island is a dangerous place, {name}. We have to worry about attacks from the Zandalari, mogu, saurok, and worst of all the Sunreavers.\n\nI had perimeter wards placed on the outskirts of our camp for additional protection. In their current state they will only injure an attacker, but I'm done with warnings!\n\nWith your help we can super-charge the wards into a more deadly defense system.", completion = "Excellent work, {name}. Those perimeter wards should keep out all manner of filth.\n\nWith Violet Rise protected we can focus on more pressing matters.", objectives = "Empower 6 Kirin Tor Perimeter Wards around Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
